insert into public.places (id,name,type,city,map_url,website,social_url,ticket,reference_url,program,origin,active) values ('place-f825dc50f78957b1c65a','Art9 Gallery','Gallery Commercial','Budapest','https://www.google.com/maps/search/?api=1&query=Art9+Gallery+Budapest','https://www.art9.hu','https://www.facebook.com/art9galeria/','Free','','{"title": "OVER", "description": "Károly Szabó’s work, which employs a deliberately limited range of means, consistently return to the problem of presence and absence, the question of identity and divergence, and the dilemmas surrounding self-representation. He creates installation scenarios in which the familiar functions of everyday objects, materials, and gestures are called into question, forcing the viewer to rethink these concepts. The exhibition’s title suggests a sense of closure, yet it also opens up the possibility of interpretation toward realms beyond the perceptible.", "artist": "Szabó Károly", "curator": "Dr. János Áfra, associate professor", "dates": "", "notes": "", "url": "https://www.facebook.com/events/1454117120021020/?acontext=%7B%22event_action_history%22%3A[%7B%22surface%22%3A%22external%22%7D%2C%7B%22mechanism%22%3A%22attachment%22%2C%22surface%22%3A%22newsfeed%22%7D]%2C%22ref_notif_type%22%3Anull%7D", "event_title": "", "event_description": "", "event_type": "", "event_url": ""}','Sheet1!A8:Q8',true) on conflict(id) do update set name=excluded.name,type=excluded.type,city=excluded.city,map_url=excluded.map_url,website=excluded.website,social_url=excluded.social_url,ticket=excluded.ticket,reference_url=excluded.reference_url,program=excluded.program,origin=excluded.origin,active=excluded.active;
insert into public.places (id,name,type,city,map_url,website,social_url,ticket,reference_url,program,origin,active) values ('place-89de34581e05b353b809','Artus Studio','Gallery Commercial','Budapest','https://www.google.com/maps/search/?api=1&query=Artus+Studio+Budapest','https://artus.hu','https://www.facebook.com/artus.studio','Free','','{"title": "LLkedés /Mestereim emlékére/", "description": "Bukta Norbert az egykori Fonó művésztelep alapítótagjaként tér vissza a Sztregova utcai gyárépület 4-5 méter magas tereibe. A tárlat az alkotó elmúlt időszakának meghatározó munkáiból mutat be több műfajt átfogó válogatást. A látogatók nagyméretű festmények, rajzok, installáció, talált tárgyak és kísérleti fotósorozatok szövetével találkozhatnak.\n„Azt, ahogy a Másik megjelenik előttem, túllépve a bennem róla kialakított képet, arcnak hívjuk.” (Emmanuel Lévinas)\nMunkásságának középpontjában a figura, a fej és a portréábrázolás áll: a külső és a belső világ feszült viszonya. Művészetében a fotó ugyanúgy működik, mint a festék vagy a grafit. A véletlenszerűen talált foltokban és formákban arcokat és “utalásokat” fedez fel, miközben a nagyméretű sorozatok ritmusát tiszta színfelületek és a telefonja által véletlenül lőtt „zsebfotók” bontják meg, új rétegeket adva az élményhez.\nA kiállítás anyaga a kincugi – a törött cserépedények arannyal való összeillesztésének – radikális filozófiájával rezonál. Nem elrejti a sebeket, traumákat és a múlt töredékeit, hanem felvállalja.\n„Rá kellett vennie magát, hogy nézzen, és ne azzal foglalkozzon, amit gondol, vagy érez.” (Nádas Péter)", "artist": "Bukta Norbert", "curator": "", "dates": "November 6–24, 2026", "notes": "", "url": "", "event_title": "Vakfolt", "event_description": "Ha nem csak a szememre, hanem önmagam egészére vonatkoztatom, akkor a vakfolt több, mint metafora.\nA vakfolt jelenség nehézsége, hogy valójában nem is tudok arról, amit nem látok, ezért saját (hiányos) nézőpontomat néha hajlamos vagyok a valósággal azonosítani.\nSzemélyiségem vakfoltja egy-egy nagyon fontos én-részemet rejtheti a tudattalanba. Olyan én-részeimet, melyeket fájdalmaim és félelmeim kitakarnak, amit nem szeretek magamban, vagy ami olyan emléket, traumát őriz, amivel nem tudok szembenézni.\nA nehézség az, hogy nem tudom, hogy nem tudom.\nInnentől a belső kérdések megindulnak: Látod magad? Látod a világot? A valóságot látod?\nHol vannak személyiséged, érzelmeid és gondolkodásod vakfoltjai? Mivel nem mersz, nem tudsz, nem akarsz szembenézni?\nA biológiai vakfolt valójában nem hiány, hiszen a szem szerkezetének természetes, egészséges része, ami pedig arra tanít, hogy amit valóságnak látok, az sosem maga a teljesség.\nA bölcsesség lehetősége talán azon paradoxon elfogadásában rejlik, hogy míg arra törekszünk, hogy vakfoltjainkat megszüntetve merjük az igazat látni, felismerjük és elfogadjuk, hogy hiányosságaink által vagyunk teljesek, vakfoltjainkkal együtt vagyunk azok, akik valójában vagyunk. (G.G.)", "event_type": "Performance", "event_url": "https://www.facebook.com/events/1099113469609354/?acontext=%7B%22event_action_history%22%3A[%7B%22surface%22%3A%22external%22%7D%2C%7B%22mechanism%22%3A%22attachment%22%2C%22surface%22%3A%22newsfeed%22%7D]%2C%22ref_notif_type%22%3Anull%7D"}','Sheet1!A9:Q9',true) on conflict(id) do update set name=excluded.name,type=excluded.type,city=excluded.city,map_url=excluded.map_url,website=excluded.website,social_url=excluded.social_url,ticket=excluded.ticket,reference_url=excluded.reference_url,program=excluded.program,origin=excluded.origin,active=excluded.active;
