insert into public.places (id,name,type,city,map_url,website,social_url,ticket,reference_url,program,origin,active) values ('place-0b4653c757c21be99641','Barcsay Hall / Hungarian Academy of Fine Arts','University','Budapest','https://maps.app.goo.gl/PheMoBxfpDhjdPap7','https://www.mke.hu','','','','{"title": "", "description": "", "artist": "", "curator": "", "dates": "", "notes": "", "url": "", "event_title": "Student Art Auction", "event_description": "For the third consecutive year, the Hungarian University of Fine Arts’ jumpSTART programme will culminate in the Student Art Auction. One of the initiative’s distinctive features is that all proceeds from the sale of artworks directly benefit the university’s students. Half of the proceeds go directly to the artists, while the other half is allocated to the university’s student welfare fund. This fund provides needs-based financial assistance to students who face difficulties covering the costs of their studies. In this way, purchasing an artwork can support not only a young artist at the beginning of their career, but also another student throughout their university years.", "event_type": "Other", "event_url": "https://www.mke.hu/news/index.php?mid=3B5Z8quHGJATxPe5s1cvqC"}','Sheet1!A11:Q11',true) on conflict(id) do update set name=excluded.name,type=excluded.type,city=excluded.city,map_url=excluded.map_url,website=excluded.website,social_url=excluded.social_url,ticket=excluded.ticket,reference_url=excluded.reference_url,program=excluded.program,origin=excluded.origin,active=excluded.active;
insert into public.places (id,name,type,city,map_url,website,social_url,ticket,reference_url,program,origin,active) values ('place-1005504a77ca9f0ea75c','Epreskert / Hungarian Academy of Fine Arts','University','Budapest','https://maps.app.goo.gl/WutbM12n3edTaAC76','https://www.mke.hu','','Free','','{"title": "Traces of Vanished Time", "description": "As part of the Strobl 170 commemorative year, historical photographs evoke the past in the atrium of the master''s former studio, paying tribute to the founder of sculpture education in Hungary.\nPreviously unseen photographic rarities in anaglyph format are presented to the public courtesy of the Alajos Strobl Memorial Foundation.", "artist": "", "curator": "", "dates": "November 6–13, 2026", "notes": "", "url": "https://www.facebook.com/events/1101332759483197/", "event_title": "", "event_description": "", "event_type": "", "event_url": ""}','Sheet1!A12:Q12',true) on conflict(id) do update set name=excluded.name,type=excluded.type,city=excluded.city,map_url=excluded.map_url,website=excluded.website,social_url=excluded.social_url,ticket=excluded.ticket,reference_url=excluded.reference_url,program=excluded.program,origin=excluded.origin,active=excluded.active;
insert into public.places (id,name,type,city,map_url,website,social_url,ticket,reference_url,program,origin,active) values ('place-b369ae65897d2fd431a1','Bartók 1 Gallery','Cafe','Budapest','https://www.google.com/maps/search/?api=1&query=Bart%C3%B3k+1+Gallery+Budapest','','https://www.facebook.com/artixxi/?locale=hu_HU','Free','','{"title": "Nagybánya 130", "description": "Group show of artists who have worked in Nagybánya (Baia Mare) over the past thirty years, marking 130 years of the artists'' colony.", "artist": "Group", "curator": "", "dates": "October 29 – November 16, 2026", "notes": "", "url": "https://www.facebook.com/events/3543568955803249/?acontext=%7B%22event_action_history%22%3A[%7B%22surface%22%3A%22external_search_engine%22%7D%2C%7B%22mechanism%22%3A%22attachment%22%2C%22surface%22%3A%22newsfeed%22%7D]%2C%22ref_notif_type%22%3Anull%7D&locale=hu_HU", "event_title": "", "event_description": "", "event_type": "", "event_url": ""}','Sheet1!A13:Q13',true) on conflict(id) do update set name=excluded.name,type=excluded.type,city=excluded.city,map_url=excluded.map_url,website=excluded.website,social_url=excluded.social_url,ticket=excluded.ticket,reference_url=excluded.reference_url,program=excluded.program,origin=excluded.origin,active=excluded.active;
insert into public.places (id,name,type,city,map_url,website,social_url,ticket,reference_url,program,origin,active) values ('place-45917daecb8d01c0bf0d','Budapest Gallery','Gallery Municipal','Budapest','https://www.google.com/maps/search/?api=1&query=Budapest+Gallery+Budapest','https://www.budapestgaleria.hu/','','Ticketed – see official website for current prices','','{"title": "A szívem is sír belül – Gyászmunkák (My Heart Also Weeps Inside – Works of Mourning)", "description": "A kiállítás fókuszában a gyász fogalma áll: személyes viszonyunk hozzá, társadalmi és szociális dimenziói, valamint az elmúláshoz kapcsolódó szokások átalakulása. A késő kapitalista társadalomban a halál egyre kevésbé az élet részeként, sokkal inkább attól izolálva, elszakadva jelenik meg; a betegség és az öregedés állapotaihoz hasonlóan fokozatosan medikalizálódott és egyre személytelenebb folyamattá vált. Ahogy a különböző átmeneti életszakaszokhoz kapcsolódó rítusaink átalakultak és sokszor meg is szűntek, úgy az életünk utolsó időszaka is egyre inkább kórházakban, magányosan, támogató közeg és megtartó tér nélkül történik. Ebben a társadalmi berendezkedésében nemcsak a halál, hanem az ahhoz kapcsolódó gyászfolyamat is már-már tabunak számít: amikor gyászolunk, kevésbé vagyunk produktívak és ezáltal hasznos tagjai a társadalomnak. A kiállítás a gyász körüli tabusítást, a kívülről jövő elvárásrendszereket és magát a láthatatlanná tételt kérdőjelezi meg azáltal, hogy a gyász jelenségének átfogó megértésére, az azzal való folyamatos munkára és a segítő közösségekre, kapcsolódásokra helyezi a hangsúlyt.\n\nA Szívem is sír belül – Gyászmunkák egyfelől olyan művészeti pozíciókat mutat be, amelyekben a gondoskodás folyamata nemcsak az élőkre, hanem az életből éppen távozókra is kiterjed. Az élőkről és holtakról való gondoskodást egy reciprokális viszonyként tételezik, amelyben az egyik nem létezik a másik nélkül. Azt az átmenetet kutatják, amely a létből a nemlétbe tart és azokat a szereplőket, akik ezen az úton támogatóként, segítőként megjelennek. Másfelől, a gyász különböző modalitásait vizsgálják a művek: a személyes veszteségektől kezdve, a megküzdési mechanizmusokon át a különböző közösségi, kollektív gyászfeldolgozási folyamatok által újragondolt és újrateremtett rítusokig. Bizonyos művek kiterjesztik a gyász fogalmát a népirtások és napjaink felfoghatatlan tragédiái felé is; olyan helyzetekre, ahol a gyászmunka nehézségekbe ütközik vagy akár lehetetlenné válik. Több alkotó reflektál a vallás megváltozott funkciójára, a spiritualizmus kortárs jelentőségére és a veszteségekhez kapcsolódó rítusok átalakulására, ezáltal a kiállítás felveti azt a kérdést is, hogy mi van a “másik oldalon” és hogyan tudunk kapcsolódni felmenőinkhez, elvesztett szeretteinkhez.\n\nKözös a kiállításon szereplő művekben, hogy a gyász folyamatára nem egy véges folyamatként vagy lezárható időszakként tekintenek, hanem olyan jelenségként, amelynek kaotikusságával és transzformatív voltával meg kell tanulnunk együtt élni. Egy szeretett személy elvesztése, egy kapcsolat megszakadása, a háborús veszteségek, vagy a globális katasztrófákkal járó áldozatok, mind a gyász szerteágazó, fájdalmas szeletei, amelyekhez a tabuk és elvárások felülírása, az ezekről való beszéd és a támogató közösségek tudnak támogatást nyújtani.\n\nA kiállítás címe Móró Zsófia Boldogok akik sírnak című művében elhangzó, Kálló Zsuzsannával készült interjúból származik.", "artist": "Noor Abed, Korakrit Arunanondchai, Anaïs Chabeur, Sári Ember, Viola Fátyol, Dana Kavelina, Emese Kádár, Adél Koleszár and Esteban de la Torre, Hilla Kurki, Zsófia Móró, Ádám Ulbert, Emily Waszak", "curator": "Gadó Flóra", "dates": "September 4 – November 22, 2026", "notes": "", "url": "https://www.facebook.com/budapestgaleria/?fref=ts", "event_title": "", "event_description": "", "event_type": "", "event_url": ""}','Sheet1!A14:Q14',true) on conflict(id) do update set name=excluded.name,type=excluded.type,city=excluded.city,map_url=excluded.map_url,website=excluded.website,social_url=excluded.social_url,ticket=excluded.ticket,reference_url=excluded.reference_url,program=excluded.program,origin=excluded.origin,active=excluded.active;
