insert into public.places (id,name,type,city,map_url,website,social_url,ticket,reference_url,program,origin,active) values ('place-127fae36f2529a03ba91','CEU Open Gallery','Gallery Municipal','Budapest','https://maps.app.goo.gl/CTdkt7SEUne66Df88','https://www.ceu.edu/civic-engagement/ceu-open-gallery','https://www.instagram.com/ceunyitottgaleria/?hl=en','Free','','{"title": "Yellow & Blue", "description": "The project presents a “mosaic” vision of Ukraine — from Carpathian peaks to seaside markets, from folk celebrations to digital creativity — reflecting its strength and identity in times of challenge.", "artist": "", "curator": "Olena Staranchuk, Anna Sarvira and Oleg Gryshchenko", "dates": "November 11–21, 2025", "notes": "", "url": "https://www.instagram.com/p/DP06lInDQMz/?hl=en&img_index=1", "event_title": "", "event_description": "🎟 Opening: November 11, 18:00\n🎨 Draw&Dine, Public guided tour and workshop: November 13, 19:00", "event_type": "Guided Tour", "event_url": "https://www.instagram.com/p/DP06lInDQMz/?hl=en&img_index=1"}','Sheet1!A16:Q16',true) on conflict(id) do update set name=excluded.name,type=excluded.type,city=excluded.city,map_url=excluded.map_url,website=excluded.website,social_url=excluded.social_url,ticket=excluded.ticket,reference_url=excluded.reference_url,program=excluded.program,origin=excluded.origin,active=excluded.active;
insert into public.places (id,name,type,city,map_url,website,social_url,ticket,reference_url,program,origin,active) values ('place-2a1ac404a2232d6a1eab','Deák Erika Gallery','Gallery Commercial','Budapest','https://www.google.com/maps/search/?api=1&query=De%C3%A1k+Erika+Gallery+Budapest','https://deakerikagaleria.hu','https://www.facebook.com/deakgaleria','Free','','{"title": "Merülés (Sinking)", "description": "Fajgerné Dudás Andrea legújabb műveiben az elmúlás és a halál tapasztalatát, férjének elvesztését dolgozza fel. A korábbi munkáira is jellemző, tabukat döngető nyers őszinteség ezúttal minden eddiginél személyesebb formában jelenik meg. Életének egyik legfájdalmasabb története mégsem marad meg az önéletrajziság keretei között: személyes vesztesége úgy válik univerzálissá, hogy a néző szinte a saját bőrén érzi a fájdalom, a hiány és a magány fizikai súlyát.\nA test Fajgerné művészetében mindig is egyszerre volt médium, téma és személyes archívum. Legújabb festményein ez a test a gyászoló test: az, amely tovább él, miközben magában hordozza a múltat, a fájdalmat, a magányt vagy a tehetetlenség érzését. A festményeken Fajgerné néhol hibrid lényként jeleníti meg férje alakját, mintha egy köztes világ lakói lennének, valahol a jelenlét és az eltűnés, az élet és a halál határán. Saját testének hús-vér anyagszerűsége Jenny Saville testképeit idézi, míg a Guernica Fajgerné fájdalmának rétegeit és a szenvedés kollektív mivoltát erősíti. A személyes tragédia egyszerre marad intim és lép túl az egyéni történeten, utalva a halál univerzális elkerülhetetlenségére.\nA művek ikonográfiájában megjelenik Durga, a harcias hindu anyaistennő alakja. Míg a sokkarú Durgát hagyományosan fegyverekkel és hatalmát jelképező tárgyakkal ábrázolják, Fajgerné saját alakját helyezi ebbe a képi hagyományba, kezéből azonban hiányoznak a harci eszközök. Kezeit ehelyett szinte könnyed tollakként ábrázolja, annak jeleként, hogy most gyengédségre és megértésre van szüksége. Ezáltal a hősi és a hétköznapi egymásba csúszik: az anya harca nem mitikus csatatéren zajlik, hanem az élet újra és újra elvégzendő feladataiban. A gyász idején a mindennapi, rutinszerű cselekvések különös jelentőséget kapnak: az életet akkor is fenn kell tartani, amikor az addigi világ rendje széthullott.\nA sorozat egyik meghatározó eleme a víz, amely a tudattalan szimbólumaként is értelmezhető. A kék és zöld árnyalatokban megjelenő víz egyszerre a túlcsorduló érzelmek, a tudattalanba száműzött emlékek és a feldolgozás közege. Vízfelületei egyszerre idézik Monet tükröződő festőiségét és a fájdalommal együtt járó sötét, ismeretlen mélységet. A zöld azonban nem csupán a víz színe: a kórházi csempe zöldje is. Az élet és a halál közötti átmeneti, steril tér emléke így beleíródik a festmények színvilágába.\nFajgerné a gyászt nem lezárható történetként vagy lineáris folyamatként, hanem az állandó átalakulás állapotaként jeleníti meg. A veszteség nyomán az élet az alámerülés és a felszínre kerülés, az elmúlás és a továbbélés, valamint az elvesztett másik jelenlétének és hiányának folyamatos újratapasztalásává válik.\nFajgerné Dudás Andrea (sz. 1985) a kortárs magyar képzőművészet egyik legizgalmasabb és legsokrétűbb alkotója, festő, feleség, feminista, performance művész és anya. 2011-ben végzett a Magyar Képzőművészeti Egyetem festő szakán, majd 2019-ben doktori fokozatot szerzett. Alkotásai megtalálhatóak számos múzeumban és magángyűjteményben. Az elmúlt években több nemzetközi rezidenciaprogramban is részt vett, legutóbb a St.A.i.R. – Styrian Artist in Residence keretein belül alkotott és állított ki Grazban.", "artist": "Andrea Fajgerné Dudás", "curator": "", "dates": "October 16 – November 20, 2026", "notes": "", "url": "https://www.facebook.com/events/1316970167105655/?acontext=%7B%22event_action_history%22%3A[%7B%22surface%22%3A%22external%22%7D%2C%7B%22mechanism%22%3A%22attachment%22%2C%22surface%22%3A%22newsfeed%22%7D]%2C%22ref_notif_type%22%3Anull%7D", "event_title": "", "event_description": "", "event_type": "", "event_url": ""}','Sheet1!A17:Q17',true) on conflict(id) do update set name=excluded.name,type=excluded.type,city=excluded.city,map_url=excluded.map_url,website=excluded.website,social_url=excluded.social_url,ticket=excluded.ticket,reference_url=excluded.reference_url,program=excluded.program,origin=excluded.origin,active=excluded.active;
insert into public.places (id,name,type,city,map_url,website,social_url,ticket,reference_url,program,origin,active) values ('place-bd7865c0cca55dbb9309','Faur Zsófi Gallery','Gallery Commercial','Budapest','https://www.google.com/maps/search/?api=1&query=Faur+Zs%C3%B3fi+Gallery+Budapest','https://galeriafaur.hu','https://www.facebook.com/FaurZsofiGallery','Free','','{"title": "Supra Omnia", "description": "A kiállítást megnyitja: Barabás Márton, Munkácsy-díjas képzőművész, Magyarország Érdemes Művésze\n„…ha lombra lomb süvölt le” – így hangzik R.M Rilke Őszi nap c. versének utolsó sora Kányádi Sándor zseniális fordításában, hozzáadva erdélyi lelkének kicsapongását. Az ősz, ugyancsak Rilke szavait idézve, maga a „szépség rettenete”. A látszólagos nyugalomba rejtett elmúlás bizonyossága.\nMunkácsy-díjas, 2024-ben Magyarország Érdemes Művésze elismerésben részesült Jovián György festőművész a klasszikus képzőművészet és az avantgárd irányzatok szintéziséből alakította ki lírai formanyelvét, melyből a tehetség, az elhivatottság és a festő lényének humanizmusa sugárzik. Világa mitologikus és filozofikus, a képzőművészeten keresztül jutott el egy keresztény felfogású egzisztencializmushoz, mely az egyéni létet tekinti a megismerés origójának, a lényeggel való szembesülést pedig az életben felmerülő határhelyzetekhez köti. Ugyanakkor művei nem nélkülözik a romantikát sem, mely az elvágyódásban, a távolba vesző, letűnt korok, vagy talán soha nem is volt világok iránt érzett nosztalgiában nyilvánul meg. Munkásságára részletgazdagság és finom kidolgozottság jellemző. A kiállításon bemutatott legújabb munkáiban festői szempontból igazi kihívás a részletek kíméletlen sokasága, a fények és árnyékok által létrehozott térérzet.\n/Zuh Deodath írásának felhasználásával/\nKiss Dániel szobrászművész munkái olyan ősképek segítségével jönnek létre, melyek már a barlangrajzok szakrális szimbolikájában és a gyermekrajzokban is fellelhetők, kollektív tudatunk őrzi őket. Nyomhagyási kényszerünk a mindannyiunkban élő forma-képeken keresztül tör felszínre, melyek az emberiség különböző civilizációiban és kultúrköreiben mindig fellelhetők voltak. Kiss Dánielt ezek egymásra gyakorolt hatása, jelentésrétegeinek átörökítése, formálódása, kollektív és szubjektív lenyomatai foglalkoztatják leginkább. Legújabb munkáiban az utánzáson alapuló és eleinte konkrét jelentés nélküli “álírás” (pseudo writing) és ennek képzőművészeti továbbgondolása, az “aszemikus írás” (asemic writing - szemantikai értelemben a tiszta vizualizáció és nyelvi felszabadulás lenyomata) jelenségét, térbeli megfogalmazását járja körül. A szobraira jellemző, a folytonosságot, az önmagukba való visszatérést megidéző formai szituációk a felhasznált anyagok (fa és kő) tekintetében is kihívást hordoznak magukban: fizikai tulajdonságaik vizsgálatától, az anyag megmunkálásának határain keresztül a cél az új, statikailag működő rendszerek megtalálása.", "artist": "Jovián György, Kiss Dániel", "curator": "", "dates": "October 14 – November 13, 2026", "notes": "", "url": "https://www.facebook.com/events/4128224447476466/", "event_title": "", "event_description": "", "event_type": "", "event_url": ""}','Sheet1!A18:Q18',true) on conflict(id) do update set name=excluded.name,type=excluded.type,city=excluded.city,map_url=excluded.map_url,website=excluded.website,social_url=excluded.social_url,ticket=excluded.ticket,reference_url=excluded.reference_url,program=excluded.program,origin=excluded.origin,active=excluded.active;
insert into public.places (id,name,type,city,map_url,website,social_url,ticket,reference_url,program,origin,active) values ('place-f0a4b12cfad5fff0b96d','Kiscelli Museum','Musuem','Budapest','https://www.google.com/maps/search/?api=1&query=Kiscelli+Museum+Budapest','https://www.kiscellimuzeum.hu/','https://www.facebook.com/kiscellimuzeum/','Ticketed – see official website for current prices','','{"title": "A diplomata – Kultúra a hidegháborúban: Guy Turbet-Delof Budapesten (1947–1958)", "description": "𝗔 𝗱𝗶𝗽𝗹𝗼𝗺𝗮𝘁𝗮. 𝗞𝘂𝗹𝘁𝘂́𝗿𝗮 𝗮 𝗵𝗶𝗱𝗲𝗴𝗵𝗮́𝗯𝗼𝗿𝘂́𝗯𝗮𝗻 – 𝗚𝘂𝘆 𝗧𝘂𝗿𝗯𝗲𝘁-𝗗𝗲𝗹𝗼𝗳 𝗕𝘂𝗱𝗮𝗽𝗲𝘀𝘁𝗲𝗻 (𝟭𝟵𝟰𝟳–𝟭𝟵𝟱𝟴) című tárlat egy francia kultúrdiplomata Magyarországon töltött éveinek történetén keresztül mutatja be a kultúra és művészet helyzetét a hidegháború első, zaklatott évtizedében. Az időszakra különböző nézőpontokból tekint: megjelenik a francia diplomácia perspektívája, a magyar politikai rendőrség ellenséges álláspontja, valamint Turbet-Delof személyes – irodalmi műveltsége és világnézete által meghatározott – látásmódja. \nA kiállítás olyan művészek munkáit mutatja be, akiknek életpályája összefonódik Turbet-Delof tevékenységével: Rozsda Endre több nagyméretű festménye és kisebb grafikái mellett Barta Lajos szobrai és szobortervei, valamint Czóbel Béla, Vilt Tibor, Vedres Márk és Gorka Géza művei is helyet kapnak. A diplomatának ajándékozott műtárgyak és a vele kapcsolatban álló művészek alkotásai mellett a politikai rendőrség lehallgatáshoz használt eszközeit, megfigyelési fotókat, jegyzőkönyveket, valamint személyes történeteket felelevenítő filminterjúkat is láthat a közönség.", "artist": "Guy Turbet-Delof (subject)", "curator": "Árvai Mária; Fábián Blanka", "dates": "October 7, 2026 – February 28, 2027", "notes": "", "url": "https://www.facebook.com/fovarosikeptar.kiscellimuzeum", "event_title": "", "event_description": "", "event_type": "", "event_url": ""}','Sheet1!A19:Q19',true) on conflict(id) do update set name=excluded.name,type=excluded.type,city=excluded.city,map_url=excluded.map_url,website=excluded.website,social_url=excluded.social_url,ticket=excluded.ticket,reference_url=excluded.reference_url,program=excluded.program,origin=excluded.origin,active=excluded.active;
insert into public.places (id,name,type,city,map_url,website,social_url,ticket,reference_url,program,origin,active) values ('place-0c4a882c7321649c49af','Fuga – Budapest Center of Architecture','Cultural Center','Budapest','https://www.google.com/maps/search/?api=1&query=Fuga+%E2%80%93+Budapest+Center+of+Architecture+Budapest','https://fuga.org.hu/','https://www.facebook.com/fuga.bek/','Free','','{"title": "Konklúzió – a PTE Művészeti Kar Design és Médiaművészeti Intézete oktatóinak kiállítása II.", "description": "A vendégeket köszönti: Dr. habil Göbölyös Luca egyetemi docens, a DMI intézet igazgatója és a fotográfia tanszék vezetője.\nA megnyitó során egy interaktív hanginstalláció is hallható lesz a PTE MK Design és Médiaművészeti Intézet munkatársainak hangjainak felhasználásával, melynek során az érdeklődők vokális és munkaeszköz-zajokból tudnak élő hangkollázst összeállítani. Készítette: Dr. habil Kovács Balázs az Elektronikus Zenei és Média Tanszék vezetője.", "artist": "Faragó Márta\nFábos György\nIllés Eszter\nKarvázy György\nKirály Fanni\nKöves Rebeka\nMucsy Szilvia\nPengő János Gergő\nPorszász Áron\nTooth Gábor Andor\nUlrich Sári\nZámori Eszter\nE. Zsemberi-Szígyártó Miklós\nSz. Eszteró Anett", "curator": "", "dates": "2026. október 9. – november 8.", "notes": "", "url": "https://fuga.org.hu/fevent/konkluzio-a-pte-muveszeti-kar-design-es-mediamuveszeti-intezete-oktatoinak-kiallitasa-ii/", "event_title": "", "event_description": "", "event_type": "", "event_url": ""}','Sheet1!A20:Q20',true) on conflict(id) do update set name=excluded.name,type=excluded.type,city=excluded.city,map_url=excluded.map_url,website=excluded.website,social_url=excluded.social_url,ticket=excluded.ticket,reference_url=excluded.reference_url,program=excluded.program,origin=excluded.origin,active=excluded.active;
insert into public.places (id,name,type,city,map_url,website,social_url,ticket,reference_url,program,origin,active) values ('place-c3f2e9eff2a0f52ced29','Godot Gallery','Gallery Commercial','Budapest','https://www.google.com/maps/search/?api=1&query=Godot+Gallery+Budapest','https://godot.hu/','https://www.facebook.com/events/s/szurcsik-jozsef-hold-villam-le/2189205904965004/?mibextid=wwXIfr&rdid=4rJc49nI7mVe4PP2&share_url=https%3A%2F%2Fwww.facebook.com%2Fshare%2F1CU1N3613L%2F%3Fmibextid%3DwwXIfr','Free','','{"title": "Hold, villám, lézer", "description": "Szurcsik József Kossuth-díjas és Munkácsy Mihály-díjas képzőművész, grafikus és festőművész, performer, zenész, a Magyar Képzőművészeti Egyetem volt rektorhelyettese, a Grafika Tanszék docense, illetve korábbi tanszékvezetője. Az 1959-ben művészcsaládba született Szurcsik József a magyar kortárs képzőművészet karakteres, azonnal felismerhető világot megteremtő alkotója. Pályája a késő szocializmus és a rendszerváltás körüli években indult. Ez az időszak nem pusztán történelmi háttér Szurcsik művészetében: munkáinak egyik visszatérő kérdése az egyén, a környezet és a hatalom egymáshoz való viszonya.\n\nMűveinek emblematikus motívuma a következetesen profilnézetben ábrázolt, karakterjegyek nélküli – és ezen személytelenség révén általános érvényűvé váló – emberi arc. Ez a metamorfikus félprofil azonban nemcsak önmagában létezik; van, hogy a tájba rejtve jelenik meg, vagy egymás mellé rendezett sorokba, uniformizált struktúrákba szerveződik, esetleg monumentális építészeti formákkal vagy különböző geometriai alakzatokkal egyesül. Ez a profilba sűrített, stiláris elem lehetővé teszi számára, hogy konkrét testek ábrázolása nélkül is az egyén, a környezet és a hatalom folyamatosan változó, újrarendeződő viszonyait mindig nyitott és egyetemes kérdésként vizsgálhassa.\n\nSzintén sajátos művészi eszközökkel ragadja meg a jelentől való elfordulás, a bezárkózás és az időtlenség ideáit. A kilencvenes évek vége felé – talán a rendszerváltáshoz fűzött remény elvesztésével összefüggésben – Szurcsik a mozdulatlan mítoszok világába zárkózik. Az antik görög kultúra szilárdsága, védelme azonban olyan, mint bármely fal, vagy mint a művész Janus-arcú fala; egyszerre véd és elrekeszt, miközben – mint motívum – asszociációk sokaságát hívja elő.\n\nAz életmű sokféleségét jól mutatja az alkalmazott technikák és műfajok gazdagsága is. Sokszorosított grafikai munkák és speciális, antik hatású, repesztett technikával készített olaj-akril képek mellett kisplasztikák, festett szerszámszobrok, színes papírinstallációk és hegesztett fémszobrok is helyet kapnak benne. Szurcsik 1985 óta állít ki, munkái Szófiától Helsinkin át New Yorkig számos nemzetközi helyszínen szerepeltek, az első kiállítását a Godot Galériában 1999-ben rendeztük. Legutóbbi kiállítása október elején nyílt Hódmezővásárhelyen, a Tornyai János Múzeumban, amely a 2025-ben elnyert Vásárhelyi Őszi Tárlat fődíjasának beszámoló kiállítása. Művei számos közgyűjteményben szerepelnek, többek között a Magyar Nemzeti Galériában, a pécsi Janus Pannonius Múzeumban, a Nemzeti Galériában Prágában vagy a dunaszerdahelyi Kortárs Magyar Galériában.\n\nA most nyíló kiállításán Szurcsik József különleges anyaggal jelentkezik. A képzőművész, grafikus, festő legkorábbi, 40 éve rejtőzködő – sőt kiállításon még nem szerepelt – festményei, kuriózumszámba menő geometrikus és szürreális kompozíciói, a pályakezdő művész energiákkal teli, izgalmas alkotásai kerülnek a közönség elé. Találkozhatunk korai korszakának grafikáival, az ún. „rendszerváltó panoptikum” könyörtelen iróniával megrajzolt alakjaival is, melyek legújabb, frissen készült munkáival kerülnek párhuzamba.", "artist": "Szurcsik József", "curator": "Kollár-Klemencz László", "dates": "2026. november 4. – 2026. december 19.", "notes": "", "url": "https://www.godot.hu/kiallitasok/szurcsik-jozsef-hold-villam-lezer", "event_title": "", "event_description": "", "event_type": "", "event_url": ""}','Sheet1!A21:Q21',true) on conflict(id) do update set name=excluded.name,type=excluded.type,city=excluded.city,map_url=excluded.map_url,website=excluded.website,social_url=excluded.social_url,ticket=excluded.ticket,reference_url=excluded.reference_url,program=excluded.program,origin=excluded.origin,active=excluded.active;
