insert into public.places (id,name,type,city,map_url,website,social_url,ticket,reference_url,program,origin,active) values ('place-9c612e5cab60682aeb5e','Godot Labor Gallery','Gallery Commercial','Budapest','https://www.google.com/maps/search/?api=1&query=Godot+Labor+Gallery+Budapest','https://godot.hu/','','','','{"title": "", "description": "", "artist": "", "curator": "", "dates": "", "notes": "", "url": "", "event_title": "", "event_description": "", "event_type": "", "event_url": ""}','Sheet1!A23:Q23',true) on conflict(id) do update set name=excluded.name,type=excluded.type,city=excluded.city,map_url=excluded.map_url,website=excluded.website,social_url=excluded.social_url,ticket=excluded.ticket,reference_url=excluded.reference_url,program=excluded.program,origin=excluded.origin,active=excluded.active;
insert into public.places (id,name,type,city,map_url,website,social_url,ticket,reference_url,program,origin,active) values ('place-ad988080095449a5391b','Három Hét Gallery','Gallery Commercial','Budapest','https://www.google.com/maps/search/?api=1&query=H%C3%A1rom+H%C3%A9t+Gallery+Budapest','https://www.37gallery.com/?fbclid=IwY2xjawVWl-1leHRuA2FlbQIxMABwZG9mAWJyaWQRMHdQcnh5UHdTVFVvdTFRV05zcnRjBmFwcF9pZBAyMjIwMzkxNzg4MjAwODkyAAEf3ESsOFS6PSZ1f5h8VFePVhMrVDW7gPAWgDR0e33JbN9iw0y9_D1dF892YiU_aem_H6gado5gQon5sajS6mpfIg','https://www.facebook.com/haromhet','Free','','{"title": "Export: Bulgaria 6 – Contemporary geometric abstraction from Bulgaria", "description": "A geometrikus művészetet illetően bulgária egykor azon kevés európai országok közé tartozott, amelyek nem rendelkeztek kialakult hagyományokkal ezen a sajátos esztétikai területen. 2010 óta azonban a nonsofia szimpóziumok, kiállítások, nyílt előadások, filmvetítések és gyermekeknek szóló műhelyek szervezésével hívja fel a társadalom figyelmét erre a művészeti irányzatra. ezen különböző tevékenységek révén az egyesületnek fokozatosan sikerült megszilárdítania a helyi művészeti közösséget, és feltenni bulgáriát a geometrikus absztrakció világtérképére. 2018-ban történelmi áttörés történt. az „export: bulgaria” első kiadását az ikkp – kunsthaus rehau-ban rendezték meg eugen gomringer meghívására. ugyanebben az évben dóra maurer tárgyalásokat kezdett a bolgár geometrikus válogatás bemutatásáról a vasarely múzeumban – ez a kezdeményezés végül 2023-ban valósult meg. később, 2024-ben a csoportos kiállítás londonba (saturation point) és leidenbe (est art foundation) is eljutott. hosszú távú együttműködésüknek és az évek során kialakult szoros kapcsolatuknak köszönhetően a nonsofia és a 37 galéria bemutatja az „export: bulgaria 6” című kiállítást. ez a tárlat georgi dimitrov, bolgár művész kurátori kezdeményezésére létrejött vándorkiállítás legújabb állomása.", "artist": "Axel Morel, Boyan Chakarov, Erdem Küçükköroğlu, Georgi Dimitrov, Georgi Georgiev, Kamen Kalev, Kamen Startchev, Maria Chakarova", "curator": "Georgi Dimitrov", "dates": "4 – 24 Nov 2026", "notes": "", "url": "https://www.facebook.com/events/1043799275344102/?acontext=%7B%22event_action_history%22%3A[%7B%22surface%22%3A%22external%22%7D%2C%7B%22mechanism%22%3A%22attachment%22%2C%22surface%22%3A%22newsfeed%22%7D]%2C%22ref_notif_type%22%3Anull%7D", "event_title": "", "event_description": "", "event_type": "", "event_url": ""}','Sheet1!A24:Q24',true) on conflict(id) do update set name=excluded.name,type=excluded.type,city=excluded.city,map_url=excluded.map_url,website=excluded.website,social_url=excluded.social_url,ticket=excluded.ticket,reference_url=excluded.reference_url,program=excluded.program,origin=excluded.origin,active=excluded.active;
