insert into public.places (id,name,type,city,map_url,website,social_url,ticket,reference_url,program,origin,active) values ('place-8972c25fe3c13b8e0619','Hegyvidék Gallery','Gallery Municipal','Budapest','https://www.google.com/maps/search/?api=1&query=Hegyvid%C3%A9k+Gallery+Budapest','https://hegyvidekgaleria.hu','','Free','','{"title": "Hajtogatott fény", "description": "Nagy Gábor György Hajtogatott fény című kiállításán a fény, a forma és a tér egymást alakító viszonya válik az alkotások meghatározó elemévé. A képzőművész munkáiban az olaj, az akril, a pasztell és a sokszorosító grafikai technikák mellett a fotó, a digitális képalkotás és a különböző képi források újraértelmezése is fontos szerepet kap. Az utóbbi években gyakran fordul hétköznapi tárgyakhoz, csendéleti helyzetekhez és geometrikus formákhoz. Művészetében régóta visszatérő motívum a kör és a gömb, valamint az ezeket kialakító fény- és ellenfényhatás. A geometrikus forma azonban nem pusztán ábrázolt motívumként jelenik meg: a fény segítségével a sík képfelületen is térbeli hatást kelt, kiemel, leválaszt vagy éppen beleolvaszt egy alakzatot a környezetébe. A kör így egyszerre válhat konkrét motívummá, kompozíciós szervezőelvvé és a fény által létrehozott vizuális jellé.\n\nNagy Gábor György alkotói praxisát a médiumok közötti átjárás és a hagyományos grafika határait tágító eljárásokkal való kísérletezés jellemzi. Műveiben visszatérően foglalkozik a mozgás illúziójának megteremtésével, a fényvisszaverő anyagok és a megvilágítás hatásaival, valamint a rétegek és áttűnések vizuális lehetőségeivel. A mostani kiállítás egyik különlegessége, hogy a művész a térbe is kilépteti grafikáit: lemezmonotípiái ezúttal nem maradnak síkban, hanem hajtogatással, hajlítással és ragasztással térbeli alakzattá válnak. A síkból kilépő grafika így nemcsak képpé, hanem a fény és az árnyék által folyamatosan változó térbeli formává is válik.", "artist": "Nagy Gábor György", "curator": "", "dates": "15 Oct – 12 Nov 2026.", "notes": "", "url": "https://hegyvidekgaleria.hu/events/hajtogatott-feny/", "event_title": "", "event_description": "", "event_type": "", "event_url": ""}','Sheet1!A26:Q26',true) on conflict(id) do update set name=excluded.name,type=excluded.type,city=excluded.city,map_url=excluded.map_url,website=excluded.website,social_url=excluded.social_url,ticket=excluded.ticket,reference_url=excluded.reference_url,program=excluded.program,origin=excluded.origin,active=excluded.active;
insert into public.places (id,name,type,city,map_url,website,social_url,ticket,reference_url,program,origin,active) values ('place-3a9886e05ec3f4e85159','Horizont Gallery','Gallery Commercial','Budapest','https://www.google.com/maps/search/?api=1&query=Horizont+Gallery+Budapest','http://www.horizontgaleria.hu/','https://www.facebook.com/horizontgaleria','Free','','{"title": "First Person View", "description": "A politikai és gazdasági világrend átalakulásának időszakát éljük, amelynek erővonalai és folyamatai még formálódni látszanak, körvonalait pedig továbbra is nehéz lenne teljes egészében átlátni. Ez az átalakulás a vizualitásunk tereiben is tettenérhető, hiszen a képek folyamatos előállítása és áramlása kíséri azt: térfigyelő kamerák felvételei, élő közvetítések, események töredékei, FPV-drónfelvételek, valamint mémek, mesterséges intelligenciával generált videók, személyes fényképek, filmek és más vizuális tartalmak ugyanabban a térben jelennek meg. A digitális platformokon a politikai események, a szórakoztatás, a reklámok és a személyes kommunikáció ugyanabban a figyelmi keretrendszerben találkoznak, ahol az ismétlődés révén a rendkívüli fokozatosan hétköznapivá válik.\nMíg bizonyos online platformokat arra használunk, hogy görgetés közben kikapcsolódjunk, vagy eltereljük a figyelmünket valamiről, addig óhatatlanul is találkozunk a valósággal, amely egy bizonytalan világ lenyomataiként jelennek meg előttünk. Ahogy ezek a képek folyamatosan váltva egymást felhalmozódnak, egyre kevesebb időt hagyva az értelmezésükre és feldolgozásukra, úgy normalizálódik a radikális.\nSzéll Ádám új műveiben ezt az átmeneti állapotot vizsgálja. Módszere szinte a képelemzéshez hasonló, hiszen a rá jellemző, rétegzett képalkotás mentén próbál közelebb kerülni azok jelentéséhez. Míg számára ez a folyamat a megismerést segíti, addig a néző számára a képek ismétlése és egymásra helyezése fokozatosan aláássa az információ olvashatóságát. A műalkotásokon minden egyes réteg hozzájárul a kompozícióhoz, növekvő sűrűségük azonban éppen azokat az elemeket fedik el, amelyekből a kép felépül. Ezáltal ahelyett, hogy a vizuális információ mennyiségének növelése tisztább, és érthetőbb képet eredményezne a néző szempontjából, sokkal inkább azt a megfoghatatlan, köztes állapotot erősíti, ami a biztos és a bizonytalan között húzódik.\nAz egyetlen tájékozódási pontot a fehéren hagyott felületek adják. A műveken megjelennek a drónfelvételek időbélyegei, a kép közepén látható célkereszt, vagy egy robbanás villanása, melyek nem mozdulnak el a rétegzés során sem. A kiállítás egyik meghatározó műve a 1964-es amerikai elnökválasztási kampányvideó kettősségéből indul ki. Egy kislány idilli környezetben virágszirmokat szedeget és számolgatja azokat, majd hirtelen egy hang visszaszámol, és egy atombomba robban fel a szemünk láttára. A kampányvideó azt sugallja, hogy a két esemény nem létezhet párhuzamosan egymás mellett, hanem le kell tennünk a voksunkat az egyik, vagy a másik mellett. De valóban ennyire fekete-fehér lenne a választás? A sűrűn rétegzett rajzokon Széll a törlés eszközét alkalmazza, olyan hiányokat hozva létre, amelyek megszakítják a vizuális információ folytonosságát. Ezek a hiányok egyszerre működnek megszakításként és viszonyítási pontként, a figyelmet arra irányítva, ami láthatatlan, vagy rejtett marad.\nA túltelítettség és a bizonytalanság állapotán túl a munkák azt is vizsgálják, hogy a képek hömpölygő áradata hogyan tágítja annak határait, amit hétköznapinak, elfogadhatónak vagy akár elképzelhetőnek tartunk. Ahogy a radikális a folyamatos kitettség révén semlegessé válik, a képek már nem pusztán tükrözik az egymás mellett létező, összeegyeztethetetlen valóságot, hanem aktívan részt vesznek annak alakításában is, ahogyan viszonyulunk ehhez az anomáliához. A vizuális kultúránk egyértelmű alakítója a társadalmi és politikai nyilvánosságunknak, ezért felmerül a kérdés, hogy a vizualitásunk miként befolyásolja, hogy mit ismerünk fel, mit tűrünk el, és végül, mit fogadunk el annak részeként.\nSzöveg: KRNÁCS Sára", "artist": "SZÉLL Ádám", "curator": "", "dates": "2026. november 11 - december 23.", "notes": "", "url": "https://www.facebook.com/events/1502288341710172/?acontext=%7B%22event_action_history%22%3A[%7B%22surface%22%3A%22external%22%7D%2C%7B%22mechanism%22%3A%22attachment%22%2C%22surface%22%3A%22newsfeed%22%7D]%2C%22ref_notif_type%22%3Anull%7D", "event_title": "", "event_description": "", "event_type": "", "event_url": ""}','Sheet1!A27:Q27',true) on conflict(id) do update set name=excluded.name,type=excluded.type,city=excluded.city,map_url=excluded.map_url,website=excluded.website,social_url=excluded.social_url,ticket=excluded.ticket,reference_url=excluded.reference_url,program=excluded.program,origin=excluded.origin,active=excluded.active;
insert into public.places (id,name,type,city,map_url,website,social_url,ticket,reference_url,program,origin,active) values ('place-7670e90062fe9b0babf6','Inda Gallery','Gallery Commercial','Budapest','https://www.google.com/maps/search/?api=1&query=Inda+Gallery+Budapest','https://www.indagaleria.hu','','Free','','{"title": "a Kazinczy János Antal (1914–2008) életműsorozat zárókiállításának megnyitójára.", "description": "The exhibition series at INDA Gallery, presenting selected works from the rich oeuvre of János Antal Kazinczy, is reaching its third and final chapter. While the first two exhibitions sought to trace the trajectory of his artistic development through distinct yet visibly interconnected periods, this time we have also brought together a small selection of works by fellow artists and close friends—Tamás Lossonczy, Endre Rozsda and Endre Bálint—as well as outstanding works by his son, János Árpád Kazinczy, who frequently provided technical assistance in the creation of his father''s works and is also the custodian of his artistic estate. Together, these works help us place the elder Kazinczy''s oeuvre within a broader context.\nBeyond possible parallels in form, use of colour and artistic concept, the juxtaposition of Kazinczy''s works with those of his friends and his son, as well as the references to the artistic and personal dialogues between them, help evoke the intellectual and historical milieu in which these works were created.", "artist": "Kazinczy János Antal", "curator": "Zsolt Kozma", "dates": "22 Oct – 27 Nov 2026.", "notes": "", "url": "https://www.facebook.com/events/1768969127647815", "event_title": "", "event_description": "", "event_type": "", "event_url": ""}','Sheet1!A28:Q28',true) on conflict(id) do update set name=excluded.name,type=excluded.type,city=excluded.city,map_url=excluded.map_url,website=excluded.website,social_url=excluded.social_url,ticket=excluded.ticket,reference_url=excluded.reference_url,program=excluded.program,origin=excluded.origin,active=excluded.active;
insert into public.places (id,name,type,city,map_url,website,social_url,ticket,reference_url,program,origin,active) values ('place-6d0275e0e511e91991fe','ISBN books+gallery','Other','Budapest','https://www.google.com/maps/search/?api=1&query=ISBN+books+gallery+Budapest','https://www.isbnbooks.hu/','https://www.facebook.com/isbnplusz/','Free','','{"title": "", "description": "", "artist": "", "curator": "", "dates": "", "notes": "", "url": "", "event_title": "", "event_description": "", "event_type": "", "event_url": ""}','Sheet1!A29:Q29',true) on conflict(id) do update set name=excluded.name,type=excluded.type,city=excluded.city,map_url=excluded.map_url,website=excluded.website,social_url=excluded.social_url,ticket=excluded.ticket,reference_url=excluded.reference_url,program=excluded.program,origin=excluded.origin,active=excluded.active;
insert into public.places (id,name,type,city,map_url,website,social_url,ticket,reference_url,program,origin,active) values ('place-3c7905802da464c5ebeb','K.A.S. Gallery','Gallery Commercial','Budapest','https://www.google.com/maps/search/?api=1&query=K.A.S.+Gallery+Budapest','https://kasgaleria.hu/','https://www.facebook.com/kasgaleria','Free','','{"title": "ÉRTELMEZÉS ALLEGÓRIÁJA", "description": "Az elmúlt években művészeti alkotó munkafolyamatomban és kiállításaimon videó-installált tereket, performanszokat, virtuális folyamatokat mutatok be, ahol a természettudományos analógiák szerepet kaptak, valamint képzőművészeti közegben társművészeti áthatásokat alkalmazok.\nA kiállításon egy külső nézőpontból szemlélő világunk összefonódásának vázlatát, az idő szerkezeti szimbólumait, a megfigyelő allegorikus modellképét szemléltetem, ahol a „fény”, mint „alapmérték”, a jel „metrikája” tekint a horizont figyelmére.\nEzek a performatív modellek, a kiállítás objektjei, mint metaforák szerepelnek, ahol a tér és az idő kísérleti felületein kiemelt szerepeket kapnak.\n„Az értelmezés allegóriája” című új munkámban megidézem a „horizont - mező” humán retorikáját, ahol a figyelem vetületében, a dolgok középpontjában újra találkozik a gondolat a tér-installáció allegorikus modellképével.\nKoroknai Zsolt DLA habil.", "artist": "KOROKNAI Zsolt", "curator": "", "dates": "06 Nov – 11 Nov 2026.", "notes": "", "url": "https://www.facebook.com/events/908201772259661/?acontext=%7B%22event_action_history%22%3A[%7B%22surface%22%3A%22external%22%7D%2C%7B%22mechanism%22%3A%22attachment%22%2C%22surface%22%3A%22newsfeed%22%7D]%2C%22ref_notif_type%22%3Anull%7D", "event_title": "", "event_description": "", "event_type": "", "event_url": ""}','Sheet1!A30:Q30',true) on conflict(id) do update set name=excluded.name,type=excluded.type,city=excluded.city,map_url=excluded.map_url,website=excluded.website,social_url=excluded.social_url,ticket=excluded.ticket,reference_url=excluded.reference_url,program=excluded.program,origin=excluded.origin,active=excluded.active;
insert into public.places (id,name,type,city,map_url,website,social_url,ticket,reference_url,program,origin,active) values ('place-09db87b73def22a6409c','Karinthy Salon','Gallery Municipal','Budapest','https://maps.app.goo.gl/mEN5Q3yeB1MvZdNY6','','','','','{"title": "", "description": "", "artist": "", "curator": "", "dates": "", "notes": "", "url": "", "event_title": "", "event_description": "", "event_type": "", "event_url": ""}','Sheet1!A31:Q31',true) on conflict(id) do update set name=excluded.name,type=excluded.type,city=excluded.city,map_url=excluded.map_url,website=excluded.website,social_url=excluded.social_url,ticket=excluded.ticket,reference_url=excluded.reference_url,program=excluded.program,origin=excluded.origin,active=excluded.active;
insert into public.places (id,name,type,city,map_url,website,social_url,ticket,reference_url,program,origin,active) values ('place-164ebe0f85b91c9055b2','Kassak Museum','Musuem','Budapest','https://www.google.com/maps/search/?api=1&query=Kassak+Museum+Budapest','https://kassakmuzeum.hu/','https://www.facebook.com/KassakMuzeum','Ticketed – see official website for current prices','','{"title": "Késem alatt – Kassák kortárs művészeti díj 2025 (Under My Knife – Kassák Contemporary Art Award 2025)", "description": "Januško Klaudia Késem alatt című egyéni kiállítása a női test alakíthatóságának ellentmondásaiból indul ki. A módosítás önalakítást ígér, ugyanakkor azokhoz a normákhoz is igazodik, amelyek kijelölik, milyen test számít kívánatosnak. A szépészeti beavatkozások és a videójátékok testre szabható karakterei itt egymás mellé kerülnek: mindkettő az Én egy másik változatának lehetőségét kínálja.       \n\nA videójátékok női szereplői régóta visszatérő figurák Januško munkáiban. A fetisizált nőképeket kifordítja, miközben megtart valamit abból a túlzó és egyben vonzó képi világból, amelyből származnak. A Késem alatt ezt az érdeklődést mozdítja tovább a szépészeti beavatkozások és a fizikai test alakíthatósága felé. Fanyar humor tartja nyitva a feszültséget erőszak és vonzerő között.     \n\nA kiállítás műtőt idéző, színpadszerű környezetében a beavatkozás eszköztára és a videójátékok tárgyvilága csúszik egymásba. A látogató egyszerre lehet szemlélő és potenciális páciens. A térben elhelyezett műtőtálakból videójáték-karakterek monológjai szólnak; a játékbeli halál így a fizikai test öregedésével és végességével kerül kontrasztba. A Késem alatt cím ezt a kettősséget sűríti: kés alá kerülhet a test, de ugyanígy azok a képek és karakterek is, amelyekből az alkotó dolgozik.  Az alakíthatóság egyszerre jelenthet kiszolgáltatottságot és cselekvési lehetőséget – más kés alatt lenni, és más kézben tartani a kést. Januško tudatosan használja ennek a látványvilágnak a vonzerejét, amely a kritikai felismerés után sem tűnik el. Az önalakítás vágya és az alkalmazkodás elvárása így nem válik szét élesen: a választás személyes marad, formáit mégis képek, technológiák és társadalmi elvárások alakítják. A test változtatása így nemcsak személyes gesztus, hanem válasz is azokra a társadalmi és gazdasági rendszerekre, amelyek a női testet formálják, értékelik és használják – miközben az ellenállás eszközei sem függetlenek attól, amivel szemben létrejönnek.    \n\nJanuško Klaudia a Kassák kortárs művészeti díj 2025 nyertese. A Késem alatt a díjhoz kapcsolódóan létrehozott új munkáit mutatja be.      \n\nJanuško Klaudia 2024-ben szerzett diplomát a Magyar Képzőművészeti Egyetem Festőművész szakán. Erasmus-ösztöndíjjal tanult a finn Aalto Egyetem Visual Cultures, Curating, and Contemporary Art programjában, jelenleg az Oslo National Academy of the Arts Fine Art mesterszakának hallgatója. 2022 óta számos csoportos kiállításon vett részt, többek között az acb Galériában, a Trafó Galériában, a Fiatal Képzőművészek Stúdiójában, illetve New Yorkban, Párizsban, Athénban. Önálló kiállításai az elmúlt időszakban a finn Aalto Egyetem V2 Galériájában, a Liget Galériában, az acb Galériában és a Művház galériaterében voltak láthatóak. 2024-ben kurátori gyakornokként vett részt az izlandi SÍM Residency programban. 2025-ben a párizsi Cité Internationale des Arts, 2026-ban a lengyelországi Goyki 3 Art Inkubator művészeti rezidenciaprogramjának ösztöndíjasa volt. 2025-ben nyerte el a Kassák kortárs művészeti díjat, valamint döntőse volt a TÓTalJOY-díjnak és a MODEM-díjnak. Legutóbb elnyerte az ACAX -díjat, amelynek keretében 2027-ben kéthónapos ösztöndíjas rezidenciaprogramon vesz részt New Yorkban, a Residency Unlimited programjában, a Trust for Mutual Understanding támogatásával.", "artist": "Januško Klaudia", "curator": "Török Krisztián Gábor", "dates": "2026. október 10. – 2027. február 07.", "notes": "", "url": "https://kassakmuzeum.hu/hu/kiallitas/idoszaki-kiallitas/janusko-klaudia-kesem-alatt", "event_title": "", "event_description": "", "event_type": "", "event_url": ""}','Sheet1!A32:Q32',true) on conflict(id) do update set name=excluded.name,type=excluded.type,city=excluded.city,map_url=excluded.map_url,website=excluded.website,social_url=excluded.social_url,ticket=excluded.ticket,reference_url=excluded.reference_url,program=excluded.program,origin=excluded.origin,active=excluded.active;
insert into public.places (id,name,type,city,map_url,website,social_url,ticket,reference_url,program,origin,active) values ('place-3b5180f8760c46f509cf','Kisterem Gallery','Gallery Commercial','Budapest','https://www.google.com/maps/search/?api=1&query=Kisterem+Gallery+Budapest','https://kisterem.hu/','https://www.facebook.com/kisterem','Free','','{"title": "The Human Body, For Machines", "description": "Amikor 1972-ben útnak indult a Pioneer-10 űrszonda, egy arannyal bevont alumíniumlapot is magával vitt, amelyen az emberiség megpróbálta megmutatni magát egy elképzelt földönkívüli civilizációnak. A plakett készítőinek ehhez olyan formát kellett találniuk, amelyről feltételezhették, hogy egy számukra ismeretlen értelem számára is megfejthető lehet. A különféle tudományos ábrák mellett két meztelen emberi alak is helyet kapott rajta. Az emberiség egészének önreprezentációja a test látható formájára támaszkodott, mintha annak felépítése és arányrendszere valamiféle, a kulturális meghatározottságokon túlmutató evidenciával rendelkezne. Mintha a test volna önmagunk azon része, amely a legkevesebb magyarázatra szorul, amelynek felismerhetősége túlélheti a közös nyelv és tapasztalat hiányát is. Pedig ami számunkra magától értetődően emberi alak, az az ismeretlen másik számára korántsem feltétlenül az. A megmutatkozás szándéka így magában hordozza a másik nézőpontjának elképzelését és a fordítás problémáját is, vagyis hogy miként jeleníthetjük meg önmagunkat úgy, hogy az ábrázolás a saját érzékelési és értelmezési kereteinken kívül is hozzáférhetővé váljon. Hiszen amikor a másik számára igyekszünk érthetővé tenni valamit, óhatatlanul saját elképzeléseinkből indulunk ki arról, hogy mit és hogyan lesz képes befogadni. \n\nAz emberi test, gépeknek. Fusz Mátyás legújabb kiállításának címe valami egészen hasonló szándékot fogalmaz meg, amennyiben az emberi testet egy tőlünk különböző másik számára próbálja hozzáférhetővé tenni, noha a címzett ezúttal egy nagyon is valóságos technikai működés. A részes eset egészen hétköznapi nyelvi viszonyt teremt: valamit valakinek, valaminek készítünk, mutatunk; valamiféle odafordulást sejtet, és annak feltételezését, hogy a megmutatkozás módját a címzett sajátosságaihoz is igazítjuk. A gépeknek szánt test így az ábrázolás és közvetíthetőség kérdését helyezi előtérbe: hogyan alakítható át egy emberi nézőpontból létrehozott kép úgy, hogy az egy másféle, tőlünk merőben eltérő működés számára is megragadhatóvá váljon? Fusz műveiben e kérdés kap konkrét formát a festészet és a digitális gyártástechnológiák keresztmetszetében, ahol a kép egyazon alkotói folyamaton belül eltérő szabályok, folyamatok és leképezési elvek mentén alakul át. \n\nA galéria terében látható művek egy több, egymásra épülő munkafázisból álló folyamat eredményei, amelynek kiindulópontját emberalakokat ábrázoló festmények adják. A képeken megjelenő alakok felismerhetően emberiek, miközben bizonyos pontokon eltávolodnak a test megszokott képi megjelenésétől, sajátos feszültséget teremtve ismerősség és idegenség között. A festmények ezt követően magassági térképekként (heightmap) szolgálnak digitális feldolgozáshoz. A magassági térkép olyan képi adatreprezentáció, amelyben az egyes pontok világossági értékeihez térbeli magasságok rendelhetők. A világosabb felületek így magasabb, a sötétebbek alacsonyabb térbeli pozícióknak feleltethetők meg, a tónusok közötti átmenetek pedig a létrejövő felület domborzatát alakítják. Az így meghatározott háromdimenziós geometria 3D-nyomtatás révén fizikai formát ölthet, jelen esetben domborművek és szobor formájában. A gépi eljárás nem az ábrázolt emberi testet ismeri fel, és nem is a festmény jelentését fordítja le valamiféle térbeli megfelelőre, hanem olyan számszerű összefüggések szerint dolgozza fel a képet, amelyek számára a váll, a mellkas vagy egy végtag a felület más pontjaihoz viszonyított értékek együtteseként jelenik meg. A festményből így olyan objektum jön létre, amelynek formáját a kiinduló kép határozza meg, és amely annak sajátosságait még magán viseli, de amelynek térbeli viszonyai már másfajta törvényszerűségek szerint szerveződnek. Fusz ezt követően a gépi eljárással létrehozott domborművek felületét ismét tovább alakítja, a festmény tehát előbb adattá, majd térbeli objektummá válik, végül pedig ismét az emberi kéz formáló tevékenységének tárgya lesz – a folyamat így embertől géphez, majd géptől emberhez vezet vissza. Kép és objektum között nincs maradéktalan megfelelés: ami az emberi tekintet számára jelentéktelennek tűnik, a gépi feldolgozás során meghatározóvá válhat, és olyan formai sajátosságokat eredményezhet, amelyek a festményen korábban nem voltak jelen. A gépi eljárásból adódó eltérések, apró kisiklások és olykor váratlan következmények pedig újabb megfigyelések kiindulópontjaivá válnak. Festmény és objektum így egymás felől válnak újraértelmezhetővé, a művész pedig olyasvalamivel találkozik újra, amelyet bár maga hozott létre, időközben részben idegenné vált számára. Felmerül, hogy voltaképpen mi biztosítja a figurák azonosságát az átalakulások során, és hol húzódnak a felismerhetőség ingatag határai: mely jegyek szükségesek ahhoz, hogy továbbra is emberi testként tekintsünk rájuk? Mennyiben marad ugyanaz az ábrázolt test, ha az azt alakító gép számára annak emberi mivolta nem bír jelentőséggel? \n\nFusz művészeti praxisában régóta meghatározó az a különös figyelem, amellyel az emberi tapasztalat sokszor nehezen megragadható jelenségei felé fordul, és amellyel a magától értetődőben valami további megismerésre érdemest fedez fel. Kíváncsiságát rendszerint maga teremtette módszertani keretek között tartja fenn: szabályokat állít fel, eljárásokat talál ki,  amelyek a figyelem sajátos kerülőútjait rajzolják ki, és amelyek révén egy ismerős jelenség új oldaláról mutatkozhat meg. Ezek a módszerek egyszerre adnak irányt a vizsgálódásnak és teremtenek lehetőséget arra, hogy a megfigyelés tárgya ellenálljon a róla alkotott előzetes elképzeléseknek. A figyelem így időben kibontakozó gyakorlat, türelmes játék, amelyben a látszólag jelentéktelen részletek, az észlelés apró bizonytalanságai és a véletlenszerűnek tűnő összefüggések egyaránt jelentőségre tesznek szert. A megismerés lassú közeledés, kitapogatózás, amelyben a világ megismerhetőségébe vetett, szinte gyermeki bizalom annak belátásával társul, hogy a megfigyelés tárgya sosem meríthető ki egyetlen nézőpontból. A gépi feldolgozás bevonása ennek a figyelemnek egy újabb formáját alakítja. Ahhoz, hogy a kép a kívánt módon váljon feldolgozhatóvá, a művésznek a festés során számolnia kell a gép lehetőségeivel és korlátaival. A technikai eljárás sajátosságainak figyelembevétele ezért az alkotói gondolkodásba is beépül, hiszen Fusz saját alkotását egy tőle eltérő működés lehetőségei felől kénytelen szemügyre venni. Ebben van valami a közös nyelv keresésének kísérletező természetéből. A kölcsönös megértés lehetősége gyakran egy olyan közös kiindulópont megtalálásán múlik, amelynek érdekében a résztvevők hajlandók módosítani megszokott vagy számukra kényelmes kifejezésmódjukon. Noha úgy tűnik, ebben az esetben a viszony aszimmetrikus, Fusz mégis úgy közelít a géphez, mint amelynek sajátos működését érdemes megismerni, és amelyhez saját alkotói döntéseit is hozzáigazíthatja. A géppel való kooperáció, annak ágenciaként való fellépése így egyben kompromisszumkeresés. Fusz bizonyos mértékig lemond a mű alakulásának közvetlen ellenőrzéséről, miközben éppen ezzel teremt lehetőséget olyan formai megoldásokra, amelyek csupán a festészet eszközeivel nem jöhettek volna létre. Együttműködésük a kontroll és az átengedés, a szándékosság és az előre nem látható következmények közötti érzékeny egyensúlyban bontakozik ki. \n\nA munkák időbelisége szintén ebből a sajátos alkotói viszonyból következik. A festés lassúsága, a felület alakulásának folyamatos követése, a formák hosszas keresése és alakítása, majd a gépi feldolgozás sajátos ritmust kölcsönöz a műveknek, és feltételez olyan időtapasztalatot, amelyben az alkotás és a megfigyelés nehezen választható el egymástól. A technológia alkalmazása így paradox módon a figyelemre fordított időt növeli meg, eltávolodva attól a produktivista időfelfogástól, amely a technikai fejlődés értelmét elsősorban a munkavégzés felgyorsításában és az emberi ráfordítás csökkentésében látja.\n\nA kiállítás egésze végső soron saját nézőpontunk korlátaira és az emberi tapasztalat viszonylagosságára irányítja a figyelmet; ami számunkra ismerős és egyértelmű, egy másik nézőpontból elveszítheti magától értetődőségét, és vele együtt meginoghat az a bizonyosság is, amellyel a világ felé fordulunk. Az emberi észlelés és értelmezés kizárólagosságának kérdése így a másikhoz való közeledés lehetőségével kapcsolódik össze, amely talán éppen a megszokott értelmezési kereteink részleges felfüggesztésével kezdődik.\n\nMajor Alexa", "artist": "Fusz Mátyás", "curator": "", "dates": "14 Oct – 13 Nov 2026.", "notes": "", "url": "https://www.facebook.com/events/1123005830246513/?acontext=%7B%22event_action_history%22%3A[%7B%22mechanism%22%3A%22attachment%22%2C%22surface%22%3A%22newsfeed%22%7D]%2C%22ref_notif_type%22%3Anull%7D", "event_title": "", "event_description": "", "event_type": "", "event_url": ""}','Sheet1!A33:Q33',true) on conflict(id) do update set name=excluded.name,type=excluded.type,city=excluded.city,map_url=excluded.map_url,website=excluded.website,social_url=excluded.social_url,ticket=excluded.ticket,reference_url=excluded.reference_url,program=excluded.program,origin=excluded.origin,active=excluded.active;
insert into public.places (id,name,type,city,map_url,website,social_url,ticket,reference_url,program,origin,active) values ('place-d82bb971422e628b151a','Knoll Gallery','Gallery Commercial','Budapest','https://www.google.com/maps/search/?api=1&query=Knoll+Gallery+Budapest','http://budapest.knollgalerie.at/966.html','','Free','','{"title": "Nyílt terek vágya - A gyaloglás formái", "description": "Nyílt térben szabadon mozogni rendkívüli élmény - s akár a biztos társadalmi státusz teszi lehetővé, akár annak hiányából, kényszerből következik, a szabadság vágya ösztönzi, s a felszabadulás, sőt a megmenekülés módja lehet.\n\nA gyaloglás, a séta, a vándorlás - a mozgás alapvető formái - kulturális toposszá váltak, ám jelenbeli gyakorlatait, meghatározó formáit áttekintve követhejtük, mi határozza meg krízisekkel teli jelenünket és a jövőnk esélyeit. \n\nAki lépdelni kezd, egyszerre tapasztalja és jelzi is saját jelenlétét. De a távollét érzését is átélheti egyúttal, a hétköznapi kötöttségek helyszíneitől eltávolodva vagy épp formáik ellen fellépve. Ám nemcsak a demonstrálók, felvonulók élhetik át cselekvőképességüket, hanem az egyszerű sétálók, a vándorok, a zarándokok, de a menekülők is. Haladás közben testük mozgásával, közvetlen, érzéki formában mérik fel a teret, s egyúttal saját teljesítőképességüket is. Így a táj egyszerre lesz intenzív testi és phiszés tapasztalat helyszíne, a gyalogló pedig önreflexiót él át. A gyaloglás maga és a nyílt terek vágya így erősitik meg tehát az identitást.\n\nA tájat eközben - még ha korábbról jól ismert hely is - a séta során atópiaként, „máshol“-ként éljük meg, s hirtelen egyszerre lesz felszabadító és megnyugtató. A mozgás folytonossága és a helyzet átmenetisége pedig - paradox módon - együtt alakít ki stabilitást. A ritmusára így rátaláló test és az ellazult elme számára, amely átadja magát időnek és térnek, az addig felfoghatatlan dolgok érthetővé, a rejtélyek megfejthetővé válhatnak. Augustinus a „solvitur ambulando“, azaz a „séta által megoldandó“, kifejezéssel utalt ezen állapot lehetőségeire, s így egyértelmű, hogy miért vált korábban a séta az ókori görög filozófusok számára is a gondolkodás és a tudásmegosztás alkalmává.\n\nÁm a gyaloglás nemcsak a megismerés, hanem a megújulás aktusává is lehet, hisz egy terület bejárása során tudományos, ökölógiai tapasztalatokat szerezve változáshoz járulhatunk hozzá. Míg a klimaváltozás miatt más létformákkal szimbiózisra kényszerülők mindig mozgó közösségekben élhetik túl a természetben előidézett változásokat. A táj maga pedig nagy menetelések kapcsán a nyilvánosság helyszínévé válhat, s a városi tájon túl a vidéki táj is telítődhet ezzel a jelentéssel.\n\nA szabadság és a megmenekülés lehetőségei villannak így fel, s egyúttal az is, hogy nagy tereket bejárva és megélve nemcsak a bezártság vagy a blokkoltság érzésétől szabadulhatunk meg. Egy metafizikai élményt is átélhetük, azt, hogy otthon lehetünk, otthonra lelhetünk a világban - azaz a jelenlét beteljesítését.\n\nA kiállításunkon megjelenő művek arra utalnak, mit jelenthetnek, s hogyan hozhatnak megoldásokat a gyaloglás különböző formái.\nA sokrétű, izgalmas témával - A gyaloglás formái - a jelenlét beteljesítése c. kiállításunkat követően - második alkalommal foglalkozunk tárlat formájában.\n\nKöszönet Sóti Mártonnak", "artist": "Chilf Mária (HU), Mara Mattuschka (AT), Garancsi Tilda (HU), Nemes Csaba (HU), Todoroff Lázár (HU), J. Nagy András (HU) és mások", "curator": "Pilinger Erzsébet", "dates": "2026. október 07 – november 28.", "notes": "", "url": "", "event_title": "", "event_description": "", "event_type": "", "event_url": ""}','Sheet1!A34:Q34',true) on conflict(id) do update set name=excluded.name,type=excluded.type,city=excluded.city,map_url=excluded.map_url,website=excluded.website,social_url=excluded.social_url,ticket=excluded.ticket,reference_url=excluded.reference_url,program=excluded.program,origin=excluded.origin,active=excluded.active;
