insert into public.places (id,name,type,city,map_url,website,social_url,ticket,reference_url,program,origin,active) values ('place-ae302d89621accc24b8a','Liget Gallery','Gallery Municipal','Budapest','https://www.google.com/maps/search/?api=1&query=Liget+Gallery+Budapest','https://ligetgallery.art/','https://www.facebook.com/ligetgaleria?locale=hu_HU','Free','','{"title": "What does it mean to see a dog in a dream?", "description": "Guardian and threat, familiar and uncanny, a dog is a creature stationed at the threshold between the known and the unseen. What does it mean to see one in a dream? Could it be premonition or warning?\n\nThe artists are connected through hoast, an artist-run space in Vienna: as its founders, as artists who have exhibited there, or whose exhibitions are scheduled for the coming year. The exhibition also reflects hoast’s programmatic approach. Yet when artists curate, it is not necessarily a manifesto-like theme or theoretical construct that brings works together, but rather a feeling or a premonition. An exhibition exists before it has a title.\n\nThe works belong to a pictorial tradition in which human and animal pass into one another and the anthropomorphic becomes object. The scenes give philosophical concepts a visual form and unsettle the familiar through unexpected encounters.\n\nThe opening will feature a live performance by Marta Beauchamp.", "artist": "Marta Beauchamp, Maria Bussmann, Wolfgang Obermair, Ekaterina Shapiro-Obermair, Nazim Ünal Yilmaz", "curator": "hoast", "dates": "2026. október 28 – december 04.", "notes": "", "url": "https://www.facebook.com/events/1623337539259962/?acontext=%7B%22event_action_history%22%3A[%7B%22surface%22%3A%22external%22%7D%2C%7B%22mechanism%22%3A%22attachment%22%2C%22surface%22%3A%22newsfeed%22%7D]%2C%22ref_notif_type%22%3Anull%7D&locale=hu_HU", "event_title": "", "event_description": "", "event_type": "", "event_url": ""}','Sheet1!A36:Q36',true) on conflict(id) do update set name=excluded.name,type=excluded.type,city=excluded.city,map_url=excluded.map_url,website=excluded.website,social_url=excluded.social_url,ticket=excluded.ticket,reference_url=excluded.reference_url,program=excluded.program,origin=excluded.origin,active=excluded.active;
