insert into public.places (id,name,type,city,map_url,website,social_url,ticket,reference_url,program,origin,active) values ('place-be2319f1bd7b8fa60b20','Ludwig Museum – Museum of Contemporary Art','Musuem','Budapest','https://www.google.com/maps/search/?api=1&query=Ludwig+Museum+%E2%80%93+Museum+of+Contemporary+Art+Budapest','http://www.ludwigmuseum.hu/','https://www.facebook.com/ludwigmuseum','Ticketed – see official website for current prices','','{"title": "WALK THIS WAY. A GYALOGLÁS MŰVÉSZETE", "description": "A gyaloglás az emberi mozgás egyik legalapvetőbb formája, amely túlmutat annak nyilvánvaló praktikus, mindennapi funkcióján: kultúrtörténeti jelenségként, a megismerés és a gondolkodás eszközeként, művészeti aktusként, valamint filozófiai módszertanként is értelmezhető. A vizuális művészetekben olyan gyakorlatokra vonatkoztatható, amelyek a sétát központi folyamatként, eseményként, élményként vagy eredményként helyezik előtérbe. Kultúrtörténeti eredete az ókorba nyúlik vissza, majd a művészet 20. századi története során fokozatosan emancipálódik, önálló művészeti diskurzussá és kiállítási témává válik. \n\nAz 1921-es dadaista túrától kezdve – amely az első olyan akció, ahol a séta aktusa volt a művészeti tartalom-, a szürrealisták cél nélküli bolyongásain és a lettrista városi sodródásokon (dérive) keresztül érintkezik a fluxussal (a mindennapi élmények művészetté emelése), majd a szobrászat kiterjesztett értelmezési mezejének dematerializációs törekvéseivel. A land art-tól a performansz-művészeten át a relációesztétikáig, az elmúlt évtizedek kortárs művészetében egyre elterjedtebbé váltak a séta alapú gyakorlatok és a gyaloglás köré szerveződő kiállítások, jelentős részben a performativitás előtérbe kerülése, a társadalmi–ökológiai művészet térnyerése miatt. \n\nA séta a művészetben politikai és társadalmi dimenziókkal egészült ki, miközben erőteljesen kapcsolódik az urbanisztikához és az aktivizmushoz. A Walk This Way című nemzetközi csoportos kiállítása gyaloglást mint művészeti formát, narratív eszközt és kritikai gyakorlatot vizsgálja, olyan művek, projektek, akciók bemutatásán keresztül, amelyek a gyaloglás hétköznapi aktusát a felfedezés, a feltérképezés, az ellenállás, a politikai cselekvés eszközeként instrumentalizálják. A kiállítás többek között igyekszik körüljárni, hogyan alakíthatja a séta a fizikai és mentális tereket, valamint rákérdez arra, hogy ez az egyszerű cselekvés miként nyújthat lehetőséget a lelassulásra, a közösségi és természeti terek újrafelfedezésére, és a társadalmi, ökológiai, urbanisztikai kihívásokkal való szembenézésre.", "artist": "Francis ALŸS, BARTHA Máté, HAN Bing, CSORBA Eszter, Valie EXPORT, Hamish FULTON, FUSZ Mátyás, GALÁNTAI György, HAJAS Tibor, Mona HATOUM, HIWA K, Michael HÖPFNER, Joachim KOESTER, KORONCZI Endre, Christina KUBISCH, Marinka LIMAT, LOVAS Ilona, Miroslav MANDIĆ, MAURER Dóra, Omar MISMAR, Bruce NAUMAN, Paulo NAZARETH, Yoko ONO, Tiziana PERS, PÓLYA Zsombor, Mladen STILINOVIĆ, SUGÁR János, SZOLNOKI József, TSAI Ming-liang, Lois WEINBERGER, WOLSKY András", "curator": "Készman József, Máté Zsófia", "dates": "2026. október 9. – 2027. január 31.", "notes": "", "url": "https://www.ludwigmuseum.hu/kiallitas/walk-way-gyaloglas-muveszete", "event_title": "", "event_description": "", "event_type": "", "event_url": "https://www.ludwigmuseum.hu/program/repair-phenomenon-jovatetel-jelensege-beszelgetes-kader-attia-val", "other_programs": [{"title": "BIG BANG. TÁGULÓ GYŰJTEMÉNYI HORIZONTOK", "description": "A múzeum 1989-es alapítása óta gyűjteménye több mint ezer tétellel gyarapodott. A rendszeres időközönként megrendezett gyűjteményi kiállítások többnyire meghatározott témára épülő, adott jellegzetességen, szempontrendszeren alapuló kurátori válogatások. A mintegy hetven évet átfogó időszak, amelyben a művek létrejöttek, egyben azt is jelenti, hogy eltérő korszakokból és így különböző kontextusokból származó munkák adják a válogatások alapját. Az eredeti összefüggések és jelentéstartalmak rekonstruálása és megőrzése mellett a történeti távlat lehetővé teszi új kapcsolatok feltárását, egyéb összefüggések megjelenítését.\n\nA Big Bang összeállítás a múzeum gyűjteményének alakulását mutatja be a gyarapodások időbeli eloszlásából kiindulva. Ezt a kronologikusan kibontakozó síkot metszi a tematikus szempontrendszer logikája: a kiállítás saját időrendjében haladva, különálló szekciókra felosztva, a folyamatosan épülő gyűjteményi anyag egyedi keresztmetszetével találkozhatnak az érdeklődők. Egy hasonlattal élve, a válogatás olyan, mint egy párhuzamos narratívákban elmesélt „családtörténet”, ha úgy tetszik, a gyűjtemény családi albuma, amely számos eddig nem látott „rokont” (művet) is megjelenít, emellett érzékelteti az egyes munkák saját mikrotörténetét, a gyűjtemény súlypontjait és a gyűjtés szempontjait.\n\nA válogatás nem feltétlenül követ művészettörténeti stílusfogalmakat. Esztétikai kategóriák helyett átfogóbb kerettémákra és vezérmotívumokra fókuszál. A tizenkét egységben többek között olyan témákat jár körbe a kurátor, mint a popkultúra hatása a művészetre, a gondolat, a koncepció mint műalkotás, a technikai bravúron messze túlmutató hiperrealizmus vagy éppen az utóbbi években elterjedt, önellentmondásoktól sem mentes posztkortárs fogalma a műalkotások egy jellemző körének leírására. A kiállított műveken keresztül a látogató elgondolkodhat az utcai művészet, a falfirkák helyéről és szerepéről a kortárs művészetben, a gépek és a mozgás jelentőségéről vagy éppen a környezettudatosságot és a természetvédelmet középpontba állító ökológiai művészetről, amely túlmutat a galériák falain, és aktív részesévé válik a környezetünkről szóló társadalmi párbeszédnek.\n\nA Big Bang (magyarul: Nagy Bumm) általánosan elterjedt kifejezés a világegyetem keletkezésének ún. standard kozmológiai modelljében, amely szerint világunk egy sűrű, forró állapotból robbanásszerű (ősrobbanás) kiterjedéssel jött létre mintegy 14 milliárd évvel ezelőtt.\n\nA kiállítás vonatkozásában a fogalom mindenekelőtt arra utal, hogy a múzeum gyűjteménye az alapítástól kezdve dinamikusan növekszik – mind számát, mind jellegét tekintve: a kezdeti állomány sokszorosára bővült, miközben megjelentek benne új műfajok, technikák és művészeti médiumok. Emellett a múzeum egyetemes és hazai gyűjtési köre is változott, kiterjed újabb kulturális-földrajzi régiókra (Dél-Kelet-Európa) és országokra (pl. Albánia, Koszovó, Ukrajna stb.), ahogyan folyamatosan gyarapodik a benne megtalálható művek alkotóinak köre is.\n\nA nagy bumm (Big Bang) tehát egyfajta metafora az ősforrásból (alapítás) mint origóból kiinduló gyűjteményi építkezés leírására és jellemzésére.", "artist": "A-ONE, BORI Bálint, Joseph BEUYS, BUKTA Imre, CSATÓ József, David CSICSKAN, CSÖRGŐ Attila, DAZE, Jiří DAVID, Hervé DI ROSA, ELEKES Károly, EL-HASSAN Róza, Richard ESTES, FEHÉR László, Nat FINKELSTEIN, Andreas FOGARASI, FODOR János, FUTURA 2000, Gérard GASIOROWSKI, Sighard GILLE, Domenico GNOLI, Ion GRIGORESCU, GOSZTOLA Kitti, GULYÁS Gyula, HALÁSZ Péter Tamás, Flaka HALITI, HAVADTŐY Sámuel, Bernhard HEISIG, Geoffry HENDRICKS, HERSKO Judit, Jenny HOLZER, HORVÁTH Gideon, Oto HUDEC, Jörg IMMENDORF, KANEUJI Teppei, Lesia KHOMENKO, KICSINY Balázs, KINDER Album, KISSPÁL Szabolcs, KORTMANN-JÁRAY Katalin, LADY PINK, LAKNER László, Jean-Jacques LEBEL, Roy LICHTENSTEIN, LLRRLLRR, LOVAS Ilona, Ciprian MUREŞAN, NAGY Imre, T. G. NAZARENKO, NEMES Csaba, NEMES Márton, NOC 167, NYÁRI István, Jefhen NYIKIFOROV, PAUER Gyula, PENCK A.R., Dan PERJOVSCHI, A. Ny. PETROV, Uwe PFEIFFER, Pablo PICASSO, PINTÉR Gábor, SASS Valéria, Konrad SMOLEŃSKI, ST.AUBY Tamás, Volker STELZMANN, Mladen STILINOVIĆ, SUGÁR János, SZABÓ Ágnes, SZÉCHY Beáta, Teofan SZOKEROV, Joe TILSON, Jean TINGUELY, TOXIC, TRANKER Kata, VETŐ János, Wolf VOSTELL, Andy WARHOL", "curator": "Készman József", "dates": "2025. SZEPTEMBER 5. – 2027. JANUÁR 10.", "notes": "", "url": "https://www.ludwigmuseum.hu/kiallitas/big-bang-tagulo-gyujtemenyi-horizontok", "event_title": "", "event_description": "", "event_type": "", "event_url": "https://www.ludwigmuseum.hu/program/repair-phenomenon-jovatetel-jelensege-beszelgetes-kader-attia-val"}]}','Sheet1!A38:Q38; Sheet1!A39:Q39',true) on conflict(id) do update set name=excluded.name,type=excluded.type,city=excluded.city,map_url=excluded.map_url,website=excluded.website,social_url=excluded.social_url,ticket=excluded.ticket,reference_url=excluded.reference_url,program=excluded.program,origin=excluded.origin,active=excluded.active;
insert into public.places (id,name,type,city,map_url,website,social_url,ticket,reference_url,program,origin,active) values ('place-00ad6034690c5e37a6e4','House of Hungarian Photographers','Musuem','Budapest','https://www.google.com/maps/search/?api=1&query=House+of+Hungarian+Photographers+Budapest','https://maimano.hu/','https://www.facebook.com/maimanohaz/','Ticketed – see official website for current prices','','{"title": "A TETTEN ÉRT VÉLETLEN – RENÉ MALTÊTE (1930–2000)", "description": "René Maltête (1930–2000) életműve rendhagyó megközelítést hozott a 20. századi francia humanista fotográfiába: egy addig szokatlan, friss nézőpontból mutatta meg a mindennapok valóságát. Maltête-nél a vizuális humor és az irónia nem pusztán efemer anekdotizmus vagy felszínes narratív díszítmény, hanem magának a fotográfiának a legfontosabb, a képek szerkezetéből fakadó kifejezőeszköze. Jelen kiállítás ezen a maltête-i látásmódon keresztül vezeti be a nézőt egy olyan vizuális univerzumba, ahol az emberi alakok és az épített környezet többnyire véletlenszerű együttállásai nem csupán témák, hanem a képtér abszolút, kompozíció-szervező főszereplői.\n\nEz az egyedülálló alkotói habitus a 20. század második felének abban a szellemi és kulturális klímájában teljesedett ki, amelyet ma a francia street photography aranykoraként, a háború utáni újjáépítés és a modernizáció traumatikus, mégis dinamikus periódusaként azonosítunk. Az 1950-es, 1960-as és 1970-es évek mindennapi valóságának radikális átstrukturálódása a korszak fotográfusaitól új reprezentációs stratégiákat követelt meg. Maltête ebben a diskurzusban pozicionálta újra a humanista fotográfia határait, amikor a társadalmi tablók középpontjába a humort mint primer esztétikai minőséget emelte. Művészete ugyanakkor egy mélyen etikus magatartásban gyökerezik: a komikum nála soha nem válik a szereplők puszta kifigurázásává, cinikus gúnnyá vagy méltatlan karikatúrává. Az esendőség bemutatása helyett Maltête-et a mélyen empatikus reflexió és a tűpontos analitikus megfigyelés jellemzi, amellyel az egyén, valamint az épített vagy természetes környezet közötti egzisztenciálisan abszurd interakciókat regisztrálja. A kiállítás retrospektív jellegű, strukturált anyaga plasztikusan demonstrálja e kompozíciók belső logikáját. A látogató elé táruló képi világban a francia mindennapok hamisítatlan valósága szigorúan kalibrált vizuális párhuzamok, texturális rímek és éles formanyelvi ellentétek szigorú geometriáján keresztül artikulálódik.\n\nA véletlen azonban Maltête számára nem jelentette a spontaneitás kizárólagosságát. Fiatal korától a filmrendezés foglalkoztatta, és ez a vizuális gondolkodás fényképein is nyomot hagyott: időnként maga is megrendezett jeleneteket hozott létre, amelyekben a szereplők, a gesztusok és a környezet tudatosan alakított kompozícióvá állnak össze. E képekben ugyanakkor ugyanaz a játékos irónia és finom abszurditás működik, mint azokban a felvételekben, amelyekben a valóság kínálta váratlan helyzetet ragadta meg, mintha a véletlen és a megrendezés nála ugyanannak a sajátos képi világnak két különböző útja volna. A kétféle megközelítés határa azonban sok esetben nem húzható meg egyértelműen: nem tudhatjuk, hogy egy-egy különös, szinte hihetetlen helyzet a valóság váratlan együttállása vagy tudatosan megkomponált jelenet eredménye. Ez a bizonytalanság a képek befogadását is játékossá és titokzatossá teszi, hiszen a néző maga is részesévé válik annak a finom dinamikának, amelyben a valóság és a képzelet, a véletlen és a rendezés folyamatosan egymással játszik.\n\nMaltête témaválasztása rendkívül sokszínű: a társadalom legkülönbözőbb rétegeit és helyszíneit öleli fel. A párizsi utcák jellegzetes karakterei vagy a külvárosi negyedekben önfeledten játszó gyerekek éppúgy részei képi világának, mint a csendes vidéki terek vagy a tengerparti életképek. Bár a nagyközönség leginkább a fanyar humorú fotókkal azonosítja őt, lírai és költői vénája a teljes életművet átszövi. Ez nem véletlen, hiszen a fotográfia mellett írással és verskiadással is foglalkozott. Számára a fényképezőgép a vizuális költészet eszköze volt. Képes volt egyetlen, jókor elkapott pillanattal teljes emberi történeteket elmesélni. A hétköznapi, elillanó pillanatokból olyan sűrített narratívákat teremtett, amelyek a nézőt azonnali gondolkodásra és őszinte mosolyra késztetik.\n\nMaltête képei arra figyelmeztetnek, hogy a hétköznapok látszólagos egyhangúságában rejlő vizuális irónia, a humanista attitűd és a kompozíciós játékosság kortárs környezetünkben is tetten érhető. E jelenségek felismeréséhez vissza kell találnunk ahhoz a prekoncepcióktól mentes, tiszta látásmódhoz, amellyel a fotográfus redukálta a valóság vizuális zaját, hogy megragadja annak megismételhetetlen, sűrített pillanatait. A tárlat így az életmű előtti tisztelgésen túl olyan új szemléletmódot kínál, amely a mindennapi valóságérzékelésünket is képes derűsebbé tenni.", "artist": "", "curator": "Baki Péter", "dates": "6 Nov 2026 – 17 Jan 2027", "notes": "", "url": "", "event_title": "", "event_description": "", "event_type": "", "event_url": ""}','Sheet1!A40:Q40',true) on conflict(id) do update set name=excluded.name,type=excluded.type,city=excluded.city,map_url=excluded.map_url,website=excluded.website,social_url=excluded.social_url,ticket=excluded.ticket,reference_url=excluded.reference_url,program=excluded.program,origin=excluded.origin,active=excluded.active;
insert into public.places (id,name,type,city,map_url,website,social_url,ticket,reference_url,program,origin,active) values ('place-35bdc5c10d86ed7fcc64','Magyar Műhely Gallery','Gallery Municipal','Budapest','https://www.google.com/maps/search/?api=1&query=Magyar+M%C5%B1hely+Gallery+Budapest','','https://www.facebook.com/magyar.muhely.folyoirat/','Free','','{"title": "", "description": "", "artist": "", "curator": "", "dates": "", "notes": "", "url": "", "event_title": "", "event_description": "", "event_type": "", "event_url": ""}','Sheet1!A41:Q41',true) on conflict(id) do update set name=excluded.name,type=excluded.type,city=excluded.city,map_url=excluded.map_url,website=excluded.website,social_url=excluded.social_url,ticket=excluded.ticket,reference_url=excluded.reference_url,program=excluded.program,origin=excluded.origin,active=excluded.active;
insert into public.places (id,name,type,city,map_url,website,social_url,ticket,reference_url,program,origin,active) values ('place-f7a363dc41f15661168d','Hunagarian National Gallery','Musuem','Budapest','https://www.google.com/maps/search/?api=1&query=Hunagarian+National+Gallery+Budapest','https://en.mng.hu/','','Ticketed – see official website for current prices','','{"title": "Művészet és spiritualitás\nVálogatás Antoni Tàpies grafikai műveiből", "description": "A kabinetkiállítás Antoni Tàpiesnek, a 20. század második fele egyik meghatározó spanyol-katalán képzőművészének grafikai műveiből mutat be válogatást. A művésztől huszonhárom alkotást láthat a közönség, melyek nagy része egy magyarországi magángyűjtemény jóvoltából szerepel a tárlaton. Az anyagot a Szépművészeti Múzeum gyűjteményeiből válogatott négy mű egészíti ki.", "artist": "", "curator": "Adriána Lantos, art historian", "dates": "15 September – 22 November 2026", "notes": "", "url": "https://en.mng.hu/exhibitions/selected-graphic-works-by-antoni-tapies/", "event_title": "", "event_description": "", "event_type": "", "event_url": "", "other_programs": [{"title": "Elhivatottak\nMagyar képzőművésznők a 20. század első felében", "description": "A kiállítás a 20. század első felének magyar női alkotóinak műveiből mutat be válogatást, a tárlaton 60 női alkotó több mint 130 alkotását kronologikus, egyúttal tematikus rendezésben ismerheti meg a közönség. A nevesebb alkotók – Anna Margit, Dénes Valéria, Ferenczy Noémi, Gedő Ilka, Gráber Margit, Korb Erzsébet, Kövesházi Kalmár Elza, Lesznai Anna, Schaár Erzsébet, Szántó Piroska és Vajda Júlia – mellett számos kevésbé ismert művész (például az Új Nyolcak művészcsoport) alkotásait is felvonultatja a tárlat. A kiállításon a művészi kiteljesedést külföldön kereső, de napjainkra már nemzetközi hírű alkotók – Beöthy-Steiner Anna, Gross-Bettelheim Jolán, Anton Prinner és Reigl Judit – művei is láthatók.", "artist": "", "curator": "Dr Anna Kopócsy, lecturer at the Department of Art History, Pázmány Péter Catholic University, and Zsófia Drienyovszki, art historian at the Museum of Fine Arts – Hungarian National Gallery.", "dates": "21 October 2026 – 14 February 2027", "notes": "", "url": "https://en.mng.hu/exhibitions/dedicated-ones-hungarian-women-artists-in-the-first-half-of-the-20th-century/", "event_title": "", "event_description": "", "event_type": "", "event_url": ""}]}','Sheet1!A42:Q42; Sheet1!A43:Q43',true) on conflict(id) do update set name=excluded.name,type=excluded.type,city=excluded.city,map_url=excluded.map_url,website=excluded.website,social_url=excluded.social_url,ticket=excluded.ticket,reference_url=excluded.reference_url,program=excluded.program,origin=excluded.origin,active=excluded.active;
insert into public.places (id,name,type,city,map_url,website,social_url,ticket,reference_url,program,origin,active) values ('place-cdb27ade3565d85e6a74','MaMu Gallery','Gallery Commercial','Budapest','https://www.google.com/maps/search/?api=1&query=MaMu+Gallery+Budapest','https://mamusociety.wordpress.com/','','Free','','{"title": "HÁROM DIMENZIÓ / THREE DIMENSIONS", "description": "Papageorgiu Andrea, Méry Beáta és Székely Annamária festészetét az ember és környezete közötti kapcsolat, valamint a valóság érzékelésének különböző dimenziói kötik össze. Alkotásaikban a látható világon keresztül az emberi lét mélyebb rétegeit vizsgálják, a hétköznapiság, a természet és a tér tapasztalatát egymásra vetítve.\n\nMéry Beáta művészete a természet és az emberi lélek organikus összefonódásából építkezik. Festészete mitologikus, lírai rendszerben jeleníti meg a létezés körforgását, az elemek mozgását, az átalakulás és az újjászületés folyamatait. Képi világa a tudattalan és a láthatatlan erők vizuális megidézése.\n\nPapageorgiu Andrea a mindennapok poézisét kutatja. Képein a hétköznapi terek és tárgyak az idő és az emberi sors lenyomataivá válnak, ahol a falrepedések, elhasznált felületek és személyes környezet apró részletei a múlt és jelen közti átmenetet rögzítik.\n\nSzékely Annamária: az épített környezet és a térábrázolás kérdéseivel foglalkozik. A tükröződések, síkból kilépő formák és háromdimenziós struktúrák révén festményein a látvány, az érzékelés és a perspektíva viszonyát vizsgálja, reflektálva a kortárs városi és vizuális valóságra.\n\nA három alkotói folyamat közös gondolati alapja az emberi jelenlét és a környezet kölcsönhatása, miként hagyunk nyomot a világban, és miként tükröződik vissza mindez ránk. Művészetük a hétköznap, a természet és az épített tér síkjain keresztül vizsgálja az idő, az emlékezet és a tér közös nyelvét.\n\nA kiállítás célja, hogy e három festői szemlélet párbeszédbe lépjen egymással, és új értelmezési horizontot nyisson, a valóság látható és láthatatlan rétegeinek, az anyagi és szellemi világ összefonódásának közös vizuális térképeként.", "artist": "MÉRY Beáta Margit\nPAPAGEORGIU Andrea\nSZÉKELY Annamária", "curator": "KALLÓS Judit, művészettörténész / art historian", "dates": "2026.11.06. – 11.27.", "notes": "", "url": "https://www.facebook.com/mamu.tarsasag/?ref=embed_page", "event_title": "", "event_description": "", "event_type": "", "event_url": ""}','Sheet1!A44:Q44',true) on conflict(id) do update set name=excluded.name,type=excluded.type,city=excluded.city,map_url=excluded.map_url,website=excluded.website,social_url=excluded.social_url,ticket=excluded.ticket,reference_url=excluded.reference_url,program=excluded.program,origin=excluded.origin,active=excluded.active;
