insert into public.places (id,name,type,city,map_url,website,social_url,ticket,reference_url,program,origin,active) values ('place-8e970d15a8caf10c7fea','MissionArt Gallery','Gallery Municipal','Budapest','https://www.google.com/maps/search/?api=1&query=MissionArt+Gallery+Budapest','','','','','{"title": "", "description": "", "artist": "", "curator": "", "dates": "", "notes": "", "url": "", "event_title": "", "event_description": "", "event_type": "", "event_url": ""}','Sheet1!A46:Q46',true) on conflict(id) do update set name=excluded.name,type=excluded.type,city=excluded.city,map_url=excluded.map_url,website=excluded.website,social_url=excluded.social_url,ticket=excluded.ticket,reference_url=excluded.reference_url,program=excluded.program,origin=excluded.origin,active=excluded.active;
insert into public.places (id,name,type,city,map_url,website,social_url,ticket,reference_url,program,origin,active) values ('place-d740916c17c7162e34e5','Molnár Ani Gallery','Gallery Commercial','Budapest','https://www.google.com/maps/search/?api=1&query=Moln%C3%A1r+Ani+Gallery+Budapest','https://molnaranigaleria.hu/','https://www.facebook.com/molnaranigaleria','Free','','{"title": "Ami eddig is itt volt", "description": "A Molnár Ani Galéria őszi kiállítási programja Csonka Veronika Ami eddig is itt volt című egyéni\nkiállításával folytatódik. A tárlat kiindulópontja a megfigyelés, mint alkotói gyakorlat, ahol az alkotó azt\nvizsgálja, milyen módokon kapcsolódhatunk a természethez és a körülöttünk működő élő\nrendszerekhez egy olyan életformában, amelyet egyre inkább a városi környezet, a technológia és a\nközvetett tapasztalat határoz meg.\nA természet közelsége iránti vágy sokak számára ismerős tapasztalat, miközben a természeti környezet\nműködése gyakran távoli és nehezen érzékelhető marad. A növényeket, vizeket és más élő\nrendszereket hajlamosak vagyunk egységes háttérként szemlélni, anélkül, hogy figyelmet fordítanánk\nazokra az apró, sokszor láthatatlan folyamatokra és kölcsönhatásokra, amelyek folyamatosan zajlanak\nbennük. Csonka Veronika nem a természethez való romantikus visszatérés lehetőségét keresi,\nmunkáiban sokkal inkább azt vizsgálja, miképp alakítható ki új kapcsolat azokkal az élő rendszerekkel,\namelyeknek mi magunk is részei vagyunk.\nA kiállítás egyik személyes kiindulópontja a művész családjának zamárdi kertje, amely generációk óta\néletének része. Míg korábban a kert elsősorban a mindennapi megélhetés és a gondoskodás helyszíne\nvolt, Csonka számára emlékezeti térré és a természethez való kapcsolódás egyik fontos pontjává vált.\nEnnek nyomán készült el a különböző természeti folyamatokat rögzítő szenzoros objektum, amely a\nkertben működött a kiálítást megelőző időszakban. A beépített szenzorok a környezet különböző\nparamétereit figyelték és rögzítették, így általa olyan folyamatok váltak érzékelhetővé, amelyek a\nhétköznapi megfigyelés számára többnyire láthatatlanok maradnak. A technológia ezesetben nem a\ntermészeti tapasztalat helyettesítője, hanem a figyelem kiterjesztése, amely egy fizikailag távoli helyet\npróbál meg a szemünk láttára folyamatosan változó rendszerré alakítani.\nA technológiához való effajta hozzáállás határozza meg a kiállítás egészét. A mikroszkopikus felvételek,\npreparátumok, biológiai struktúrák, mérési adatok és lassú biokémiai folyamatok nem tudományos\nillusztrációként jelennek meg, hanem olyan kiindulópontokként, amelyeken keresztül a természet\nmegfigyelésének különböző módjai válnak tapasztalhatóvá. A festmények és objektumok részben a\nművész mikroszkópos megfigyeléseiből indulnak ki, amely laboratóriumi környezetet, metszeteket és\npreparátumokat idéző anyaghasználatában mutatkozik meg. A vásznakon megjelenő absztrakt,\norganikus formák egyszerre keltenek ismerős és idegen benyomást, amelyben a szépség és bizarrság,\na rendezettség és bomlás érzete egyaránt vannak jelen.\nA kapcsolódásunk ugyanakkor nem kizárólag tudományos vagy technológiai eszközökön keresztül\ntörténhet. Egy zárt ökoszisztéma megfigyelése, a növények gondozása vagy épp a konyhában zajló\nbiológiai folyamatok mind olyan hétköznapi helyzetek, amelyekben az ember nem pusztán szemlélője,\nhanem résztvevője az élő rendszereknek. A közvetlen tapasztalat és a technológiai eszközök így\nkülönböző lehetőségei annak, hogy közelebb kerüljünk a körülöttünk zajló folyamatokhoz.\nMindeközben az is kérdéssé válik, hogyan változik meg valamihez való viszonyunk, amikor olyan\nstruktúrákat kezdünk érzékelni benne, amelyek korábban láthatatlanok maradtak.\nAz Ami eddig is itt volt című kiállítás fókuszában nem a természetmeghatározás kérdése áll, sokkal\ninkább arra mutat rá, hogy milyen eszközökön keresztül próbáljuk megérteni, és hogyan alakítja maga\na megfigyelés a természethez fűződő kapcsolatunkat. A kiállítás a művész saját újrakapcsolódási\nkísérleteinek állomásait követi végig, miközben a néző számára is lehetőséget kínál arra, hogy közelebb\nkerüljön azokhoz a rendszerekhez, amelyek körülvesznek bennünket. Csonka Veronika alkotásain\nkeresztül nem egy elveszett, idealizált természethez való visszatérést javasol, hanem annak\nfelismerését, hogy a kapcsolat lehetősége talán sosem tűnt el teljesen, csak meg kell tanulnunk\nészrevenni azt, ami eddig is jelen volt.\nCsonka Veronika 1992-ben született Siófokon, jelenleg Budapesten él és alkot. 2019-ben végzett a\nMagyar Képzőművészeti Egyetem festő szakán. Műveit a biológia és a természethez való viszonyunk\ninspirálja. Változatos anyagú és léptékű alkotásai, legyen szó akár festményekről, akár 3D tollal felrajzolt\nobjektjeiről, az élő szövetet, rendszereket helyezik tudományos keretbe. 2024-ben nyílt első egyéni\nkiállítása Biotic mechanism címmel az am projects-ben.", "artist": "Csonka Veronika", "curator": "", "dates": "2026. szeptember 18.\n– november 20.", "notes": "", "url": "https://www.facebook.com/events/2093103941290765/?acontext=%7B%22ref%22%3A%2252%22%2C%22action_history%22%3A%22%5B%7B%5C%22surface%5C%22%3A%5C%22share_link%5C%22%2C%5C%22mechanism%5C%22%3A%5C%22share_link%5C%22%2C%5C%22extra_data%5C%22%3A%7B%5C%22invite_link_id%5C%22%3A1596195258852389%7D%7D%5D%22%7D", "event_title": "", "event_description": "", "event_type": "", "event_url": ""}','Sheet1!A47:Q47',true) on conflict(id) do update set name=excluded.name,type=excluded.type,city=excluded.city,map_url=excluded.map_url,website=excluded.website,social_url=excluded.social_url,ticket=excluded.ticket,reference_url=excluded.reference_url,program=excluded.program,origin=excluded.origin,active=excluded.active;
insert into public.places (id,name,type,city,map_url,website,social_url,ticket,reference_url,program,origin,active) values ('place-1001b70aab7052a4899f','am projects','Gallery Commercial','Budapest','https://maps.app.goo.gl/3Zbm8aGFBfKmnjxy5','','https://www.facebook.com/amprojectsbyanimolnar','Free','https://exindex.hu/en/venue/am-projects/','{"title": "Jelküszöb", "description": "Az am projects kiállítási programja Boruzs Ádám Jelküszöb című kiállításával folytatódik.\nA jelküszöb az információelméletben azt a referenciaértéket jelöli, amely meghatározza, hogy egy\nbeérkező impulzust egy rendszer már értelmezhető információként érzékel-e, vagy még a\nháttérzaj részeként marad észrevétlen. Ennek nyomán a kiállítás középpontjában az a bizonytalan\nhatárhelyzet áll, amikor valami kiemelkedik a háttérből, és jelentéshordozóvá válik számunkra.\nBoruzs Ádám festményeinek kiindulópontját hullámformák és különböző adatalapú struktúrák\nadják. Ezek a formák első pillantásra diagramokra vagy mérési eredményekre emlékeztetnek, a\nművek azonban nem konkrét tudományos jelenségeket ábrázolnak. A festészet közegébe kerülve\neredeti funkciójuk háttérbe szorul, miközben szerkezetük továbbra is jelen marad.\nA különböző hullámformák és rendszerek egymásra rétegződnek, keresztezik, részben elfedik és\nátalakítják egymást. Egy ponton már nem egyértelmű, hogy amit látunk, még az eredeti jel, annak\ntorzulása, vagy egy újonnan létrejövő mintázat. A kiállítás éppen ezt a bizonytalan átmenetet\nvizsgálja. Azt a határt, ahol az adat képpé, a jel mintázattá, az információ pedig érzéki\ntapasztalattá alakul. Így a képek nem kész válaszokat kínálnak, inkább olyan vizuális helyzeteket\nteremtenek, amelyekben a néző maga is részt vesz a jelentés létrehozásában.\nAz alkotó számára a zaj sem pusztán hiba vagy zavaró tényező. A rendezetlenségből új\nkapcsolatok és struktúrák is kialakulhatnak, ami megszakít egy információt, egyúttal valami más\nmegjelenésének feltétele is lehet. A jel és a zaj így nem egymással szembenálló fogalmak, hanem\negymást folyamatosan alakító állapotok.\nBoruzs Ádám munkáiban nem arra a kérdésre keresi a választ, hogy mit jelent egy adott jel,\nhanem arra, hogy hogyan válik valami jelentéshordozóvá számunkra. Hol húzódik a határ adat és\nkép, rendszer és mintázat, információ és érzékelés között? És mi történik egy jellel akkor, amikor\nmár nem ismerjük a forrását, mégis megpróbáljuk olvasni?\nBoruzs Ádám 2018-ban végzett a Magyar Képzőművészeti Egyetem festő szakán, majd 2019-ben\nugyanitt képzőművész-tanár képesítést szerzett. Első önálló kiállítására 2012-ben került sor.\nMunkásságát számos rangos szakmai elismeréssel díjazták, többek között 2017-ben elnyerte a\nJunior Master of Light díjat, 2020-ban a Decode „Ígéretes Projekt” díját, 2022-ben pedig elnyerte\na Budapesti Műszaki és Gazdaságtudományi Egyetem Művészeti Rezidenciaprogramjának\nlehetőségét.", "artist": "Ádám Boruzs", "curator": "", "dates": "18 September – 20 November, 2026", "notes": "", "url": "https://www.facebook.com/events/1069232609193899?acontext=%7B%22event_action_history%22%3A[%7B%22surface%22%3A%22user_timeline%22%7D%2C%7B%22mechanism%22%3A%22attachment%22%2C%22surface%22%3A%22newsfeed%22%7D]%2C%22ref_notif_type%22%3Anull%7D", "event_title": "", "event_description": "", "event_type": "", "event_url": "", "other_programs": [{"title": "Jelküszöb (Threshold of Signs)", "description": "Solo exhibition by Ádám Boruzs.", "artist": "Boruzs Ádám", "curator": "", "dates": "18 Sep – 20 Nov 2026.", "notes": "", "url": "https://exindex.hu/en/event/jelkuszob/", "event_title": "", "event_description": "", "event_type": "", "event_url": ""}]}','Sheet1!A48:Q48; Sheet1!A80:Q80',true) on conflict(id) do update set name=excluded.name,type=excluded.type,city=excluded.city,map_url=excluded.map_url,website=excluded.website,social_url=excluded.social_url,ticket=excluded.ticket,reference_url=excluded.reference_url,program=excluded.program,origin=excluded.origin,active=excluded.active;
insert into public.places (id,name,type,city,map_url,website,social_url,ticket,reference_url,program,origin,active) values ('place-b92921e6697d4e0e2356','Mucsarnok / Kunsthalle','Musuem','Budapest','https://www.google.com/maps/search/?api=1&query=Mucsarnok+/+Kunsthalle+Budapest','https://www.mucsarnok.hu/','','Ticketed – see official website for current prices','','{"title": "Műcsarnok 130", "description": "A kiállítás három termében végigkövetheti a látogató a Műcsarnok 130 évének történetét. Az első teremben egy idővonalon az 1896-os megnyitása óta eltelt időszak kiállításai és történelmi csomópontjai szerepelnek. Egy műtárgyválogatást is bemutatunk, egy-egy szoborral, festménnyel vagy grafikai lappal felvillantva néhány fontosabb kiállítást. A második és harmadik teremben a közelmúlt tárlatai kapnak nagyobb hangsúlyt, az adatos bemutatást itt is válogatott műtárgyak kísérik. Különös fókuszt kap az elmúlt hat év kiállításainak megjelenítése, így nemcsak az idővonalon, de a térben is a kezdetektől a jelen felé halad a látogató. Célunk, hogy a látogatók minél több érdekes momentumot fedezzenek fel az intézmény történetéből, és egy-egy műtárgy segítségével újra átélhessék a felidézett pillanatot.\n\nMaga az épület történelmi és urbanisztikai szempontból is egyedülálló országjelkép. A Schickedanz Albert által tervezett, neoklasszikus és antik etruszk motívumokat hordozó palotát 1896. május 4-én I. Ferenc József nyitotta meg a nemzet számára. Az épület eredeti tervrajzaiból és a külső homlokzat akvarell terveiből is bemutatunk néhányat a kiállításon. A Műcsarnok a Szépművészeti Múzeummal és a Millenniumi Emlékművel együtt alkotja a Hősök tere szimbolikus kompozícióját, a nemzeti identitás és a kiemelt állami tiszteletadás ünnepeinek szakrális, kolonnádként egybefogott központját. Az intézmény a kezdetektől fogva a magyar történelem sorsfordító pillanatainak és a művészet fordulópontjainak tanúja: dísztermében ravatalozták fel Munkácsy Mihályt, Lotz Károlyt és Zichy Mihályt, reprezentatív külső lépcsőin pedig Nagy Imrét és 1956-os mártírtársait búcsúztatták 1989. június 16-án, ami a politikai rendszerváltás történelmi nyitánya lett.\n\nA kiállítási struktúra az elmúlt 130 évben folyamatosan alkalmazkodott a kor kihívásaihoz. Az Országos Magyar Képzőművészeti Társulat által alapított, majd 1926-ban a Főváros tulajdonába, a háború után pedig állami kezelésbe került intézmény a történelmi Nemzeti Képzőművészeti Kiállítások és a szocialista korszak kezdetben ideológiailag terhelt, majd a sztálinista kánont megtörő, modernizálódó tárlatai után jutott el a jelenlegi működési formájáig. 2014 óta a Műcsarnok fenntartója a Magyar Művészeti Akadémia, ekkor indult el az öt műfajt ötéves váltásban bemutató Nemzeti Szalonok sorozata.\n\nA 2020 és 2026 közötti legfrissebb időszak újabb rendkívüli kihívások elé állította a vezetést. A Covid-járvány kitörésekor a Műcsarnok az elsők között reagált a digitális térbe való átlépéssel: virtuális séták és online tárlatvezetések segítségével a bezárt falak mögül is elvitte a művészetet az otthonok biztonságába. A pandémiát követően sikeresen állt vissza az évi több mint húsz kiállítást számláló struktúra.", "artist": "", "curator": "Kondor-Szilágyi Mária, Szegő György", "dates": "07 November, 2026 – 17 January, 2027", "notes": "", "url": "https://www.mucsarnok.hu/kiallitasok/kiallitasok.php?mid=Yr8VDp4DbTkB8Ihvcagjxl&tax=560c5eec6098a", "event_title": "", "event_description": "", "event_type": "", "event_url": "", "other_programs": [{"title": "Posters and Drawings – An Exhibition of Graphic Designer József Árendás", "description": "A Műcsarnok reprezentatív tárlattal tiszteleg a kortárs magyar kulturális plakátművészet egyik legmeghatározóbb, iskolateremtő alakja, Árendás József előtt. A kiállítás aktualitását a művész 80. születésnapja adja, amely kiváló alkalom a gazdag életmű összegzésére és rendszerezésére, valamint arra, hogy ráirányítsa a figyelmet a kulturális plakát műfajának különleges értékeire.\n\nA tárlat a „sűrített retrospektív” elméletére épül: nem a teljességre törekszik, hanem a művész alkotói DNS-ét, stílusfejlődését és főbb tematikáit mutatja be. A válogatás a legmeghatározóbb korszakokat sűríti egyetlen, vizuálisan és tartalmában is intenzív ívbe. A műcsoportok a pályaképből kiemelkedő három fő téma köré szerveződnek: az 1970-es évek nosztalgiát keltő moziplakátjai; az 1983-tól induló színházi plakátok korszaka és drámaisága; valamint az utóbbi évtizedek úgynevezett szerzői vagy autonóm plakátjai, amelyek már a tisztán művészi üzenetre koncentrálnak.\n\nA kiállítás az életmű olyan alapértékeit állítja fókuszba, mint az intellektuális humor, a fanyar irónia, a szókimondó képi metaforák, az erős atmoszférateremtés, vagy a szellemes asszociációk. Külön figyelmet szentel a mai tervezőgrafikában már ritka kincsnek számító manuális, rajzi tehetségnek, vagy az offline és a digitális technika eszközeit ötvöző művészi attitűdnek, ezért a plakátok mellett a rajzok is szerepet kapnak a térben. A tárlat nemcsak a művész munkásságát szemlélteti, hanem a műfaj történetéről és változásairól is mesél: utcai hirdetőoszlop beemelésével is megidézi a plakátok eredeti hordozóját és közegét.\n\nÁrendás József munkássága kiváló példa arra, hogy a digitális kor automatizmusai ellenére a mély gondolatiság, a szellemesség és a magas szintű grafikai megformálás hogyan emelheti a plakátot az autonóm művészet szintjére. Tárlata nem pusztán egy pálya állomásait rögzíti, hanem a kulturális plakát műfajának múlandó, mégis örök értékeit is ünnepli.", "artist": "Árendás József", "curator": "Garami Gréta", "dates": "25 September – 22 November, 2026", "notes": "", "url": "https://www.mucsarnok.hu/kiallitasok/kiallitasok.php?mid=esFkwzLvUAmamx8eN2w3Yj&tax=560c5eec6098a", "event_title": "", "event_description": "", "event_type": "", "event_url": ""}]}','Sheet1!A49:Q49; Sheet1!A50:Q50',true) on conflict(id) do update set name=excluded.name,type=excluded.type,city=excluded.city,map_url=excluded.map_url,website=excluded.website,social_url=excluded.social_url,ticket=excluded.ticket,reference_url=excluded.reference_url,program=excluded.program,origin=excluded.origin,active=excluded.active;
